insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (61, 3, 165, 171, 'سورة آل عمران ١٦٥ – ١٧١', '«أنّى هذا؟ قل هو من عند أنفسكم»، والشهداء أحياء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 61) = $j$[{"lbl": "الآيات ١٦٥ – ١٦٨", "q": "أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٦٥﴾ وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ ﴿١٦٦﴾ وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ ﴿١٦٧﴾ ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٦٨﴾", "w": [["المصيبة", "ما يصيب الإنسان من سوء، وأسوؤها مصيبة الموت."], ["مثليها", "ضعفيها؛ إذ قتلوا في بدر سبعين من المشركين وأسروا سبعين."], ["أنّى هذا؟", "من أين أتانا هذا الذي أتانا من القتل والهزيمة؟"], ["فبإذن الله", "بإرادته تعالى وتقديره، بربط المسببات بأسبابها."], ["نافقوا", "أظهروا من الإيمان ما لا يُبطنون من الكفر."], ["أو ادفعوا", "ادفعوا العدو عن دياركم وأهليكم وأولادكم إن لم تريدوا ثواب الآخرة."], ["فادرؤوا", "فادفعوا."], ["إن كنتم صادقين", "في دفع المكروه بالحذر."]], "m": "ذكر الله قول المؤمنين بعد أن أصابتهم مصيبة القتل والجراحات والهزيمة: «أنّى هذا؟» أي من أين جاءت هذه المصيبة ونحن مسلمون نقاتل في سبيل الله مع رسوله؟ فقال: أوَلمّا أصابتكم مصيبة بأحد قد أصبتم مثليها ببدر؛ إذ قُتل من المؤمنين بأحد سبعون، وقُتل من المشركين ببدر سبعون وأُسر سبعون. وأمر رسوله ﷺ أن يجيبهم: هو من عند أنفسكم، بمعصيتكم لرسول الله حين خالف الرماة أمره، وبعدم صبركم إذ فررتم من المعركة. ثم أخبر أن ما أصابهم يوم التقى الجمعان كان بقضاء الله وتدبيره، وحكمته أن يظهر المؤمنين على صورتهم الحقة، وأن يظهر الذين نافقوا، وهم عبد الله بن أُبيّ وعصابته الذين رجعوا من الطريق. وقد قال لهم عبد الله بن حرام والد جابر: تعالوا قاتلوا في سبيل الله، أو ادفعوا عن أنفسكم وأهليكم جيشاً غازياً، فإن وقوفكم معنا يكثّر سوادنا، فقالوا: لو نعلم قتالاً لاتبعناكم، فهم للكفر يومئذ أقرب منهم للإيمان، يقولون بألسنتهم ما ليس في قلوبهم، والله أعلم بما يكتمون. ثم أخبر أنهم قعدوا وقالوا لإخوانهم في النفاق: لو أطاعونا فقعدوا ما قُتلوا، فأمر رسوله ﷺ أن يردّ: فادفعوا عن أنفسكم الموت إذا حضر أجلكم إن كنتم صادقين.", "h": ["المصائب ثمرة الذنوب.", "كل الأحداث التي تتمّ في العالم سبق بها علم الله، ولا تحدث إلا بإذنه.", "قد يقول المرء قولاً أو يظن ظناً يصبح به على حافة هاوية الكفر.", "الحذر لا يدفع القدر."], "k": "«قل هو من عند أنفسكم»… حين تصيبني مصيبة، هل أبحث أولاً عن ذنبٍ أتوب منه؟"}, {"lbl": "الآيات ١٦٩ – ١٧١", "q": "وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ ﴿١٦٩﴾ فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿١٧٠﴾ ۞يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ ﴿١٧١﴾", "w": [["ولا تحسبن", "ولا تظنّن."], ["قُتلوا", "استُشهدوا."], ["أحياء", "يحسّون ويتنعّمون في نعيم الجنة بالطعام والشراب."], ["فرحين", "مسرورين."], ["لا خوف عليهم", "لما وجدوا من الأمن التام عند ربهم."], ["ولا هم يحزنون", "على ما خلّفوا وراءهم في الدنيا، لما نالهم من كرامة في الجنة."], ["يستبشرون", "يفرحون."], ["وفضل", "وزيادة."]], "m": "ما زال الحديث عن غزوة أحد، فقال الله لرسوله ﷺ: لا تظنّن الذين استُشهدوا من المؤمنين في أحد وغيرها أمواتاً لا يحسّون ولا يتنعّمون، بل هم أحياء عند ربهم يُرزقون، أرواحهم في حواصل طير خضر تأكل من ثمار الجنة وتأوي إلى قناديل معلّقة بالعرش. إنهم فرحون بما أكرمهم الله به، ويستبشرون بإخوانهم الذين خلّفوهم في الدنيا على الإيمان والجهاد بأنهم إذا لحقوا بهم لم يخافوا ولم يحزنوا، لما يصيرون إليه من نعيم الجنة وكرامة الله. والشهداء جميعاً مستبشرون بما ينعم الله عليهم ويزيدهم، وبأنه تعالى لا يضيع أجر المؤمنين، شهداء وغير شهداء، بل يوفّيهم أجورهم ويزيدهم من فضله.", "h": ["الشهداء أحياء، والمؤمنون أحياء في الجنة، غير أن حياة الشهداء أكمل.", "الشهداء يستبشرون بالمؤمنين الذين خلّفوهم على الإيمان والجهاد بأنهم إذا لحقوا بهم نالهم من الكرامة والنعيم ما نالهم.", "لا خوف ينال المؤمن الصالح إذا مات، ولا حزن يصيبه."], "k": "«وأن الله لا يضيع أجر المؤمنين»… ما العمل الذي أرجو أن أجده محفوظاً عند ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 61;
