insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (62, 3, 172, 180, 'سورة آل عمران ١٧٢ – ١٨٠', 'حسبنا الله ونعم الوكيل، والإملاء للكافرين، والتحذير من البخل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 62) = $j$[{"lbl": "الآيات ١٧٢ – ١٧٥", "q": "ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ ﴿١٧٢﴾ ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴿١٧٣﴾ فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ ﴿١٧٤﴾ إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٧٥﴾", "w": [["استجابوا", "أجابوا الدعوة وقبلوا الأمر."], ["القرح", "ألم الجراحات."], ["أحسنوا", "أتوا بأعمالهم وأقوالهم وفق الشرع، وأحسنوا إلى غيرهم."], ["اتقوا", "اتقوا ربهم فلم يشركوا به ولم يعصوه فيما أمرهم أو نهاهم."], ["حسبنا الله", "يكفينا الله ما أرادونا به من الأذى."], ["ونعم الوكيل", "نعم الوكيل الله، نَكِل إليه أمورنا ونفوّضها إليه."], ["فانقلبوا", "رجعوا من حمراء الأسد إلى المدينة."], ["أولياءه", "أهل طاعته والاستجابة له فيما يدعوهم إليه من الشر والفساد."]], "m": "الآيات الأربع في المؤمنين الذين حضروا أحداً يوم السبت، وخرجوا في طلب أبي سفيان يوم الأحد مع نبيهم ﷺ؛ إذ رأى أن يرفع معنويات أصحابه ويُرهب أعداءه، فأمر مؤذناً يؤذّن بالخروج، فاستجابوا وفيهم الجريح، حتى إن أخوين جريحين كان أحدهما يحمل أخاه، حتى انتهوا إلى حمراء الأسد، وألقى الله الرعب في قلب أبي سفيان فارتحل إلى مكة. «الذين استجابوا لله والرسول من بعد ما أصابهم القرح، للذين أحسنوا منهم واتقوا أجر عظيم»، وهو الجنة. «الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم»: القائلون نفر من عبد القيس مرّوا بأبي سفيان وهو عازم على العودة إلى المدينة، فقال لهم: أخبروا محمداً وأصحابه أني جامع جيوشي وقادم عليهم، فلما بلغهم ذلك زادهم إيماناً، وقالوا: حسبنا الله، يكفينا شرهم، ونعم الوكيل. فرجعوا سالمين في نعمة الإيمان والنصر، وفضل إذ أصابوا تجارة في عودتهم، لم يمسسهم سوء، واتبعوا رضوان الله بالاستجابة، والله ذو فضل عظيم. ثم قال: «إنما ذلكم الشيطان يخوّف أولياءه»، أي الناطق على لسان أولئك النفر يخوّفكم من أوليائه أبي سفيان وجمعه، فلا تخافوهم وخافوني إن كنتم مؤمنين، وكذلك فعلوا.", "h": ["فضل الإحسان والتقوى، وأنهما مفتاح كل خير.", "فضل أصحاب رسول الله ﷺ على غيرهم، وكرامتهم على ربهم.", "فضل كلمة «حسبنا الله ونعم الوكيل»، قالها رسول الله ﷺ، وقالها إبراهيم ﵇ من قبل.", "بيان أن الشيطان يخوّف المؤمنين من أوليائه، فعلى المؤمنين ألا يخافوا غير ربهم، فيطيعونه ويعبدونه ويتوكلون عليه، وهو حسبهم ونعم الوكيل."], "k": "ما الذي يخيفني هذه الأيام؟ هل أقول عنده من قلبي: «حسبنا الله ونعم الوكيل»؟"}, {"lbl": "الآيات ١٧٦ – ١٧٨", "q": "وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ ﴿١٧٦﴾ إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٧٧﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ ﴿١٧٨﴾", "w": [["ولا يحزنك", "الحزن: غمّ يصيب النفس لرؤية أو سماع ما يسوؤها."], ["الكفر", "تكذيب الله ورسوله فيما جاء به الرسول وأخبر به."], ["يسارعون", "يبادرون."], ["اشتروا الكفر بالإيمان", "اعتاضوا الكفر عن الإيمان."], ["إثماً", "الإثم: كل ضارّ قبيح، ورأسه الكفر والشرك."]], "m": "كشفت أحداث أحد النفاق مكشوفاً لا ستار عليه، فحصل من ذلك ألم شديد لرسول الله ﷺ والمؤمنين، فقال له ربه: لا يحزنك مسارعة هؤلاء المنافقين في الكفر، وقال «في الكفر» ولم يقل «إلى الكفر» إشارة إلى أنهم ما خرجوا منه، إذ كان إسلامهم نفاقاً. إنهم لن يضرّوا الله شيئاً، والله يريد ألا يجعل لهم نصيباً من نعيم الآخرة، فتركهم في كفرهم، ولهم عذاب عظيم. ثم حكم على الذين يرتدّون فيبيعون الإيمان بالكفر بأنهم لن يضرّوا الله شيئاً، ولهم عذاب أليم في النار. ثم أبطل ظنّ الكافرين أن إمهال الله لهم وإطالة أعمارهم خير لهم، بل هو شرّ؛ إذ كلما تأخروا يوماً اكتسبوا فيه إثماً، فيعظم ذنبهم بقدر ما تطول حياتهم، ولهم عذاب مهين، يناسب ما كانوا عليه من كبر وعلوّ وفساد.", "h": ["لا ينبغي للمؤمن أن يحزنه كفر كافر ولا فسق فاسق؛ لأن ذلك لا يضرّ الله شيئاً، وسيجزي الله الكافر والفاسق بعدله.", "لا ينبغي للعبد أن يغرّه إمهال الله له، وعليه أن يبادر بالتوبة من كل ذنب؛ إذ ليس هناك إهمال وإنما هو إمهال.", "الموت للعبد خير من الحياة؛ لأنه إن كان صالحاً فالآخرة خير له من الدنيا، وإن كان غير صالح فالموت خير له حتى لا يزداد إثماً فيوبق بكثرة ذنوبه."], "k": "«إنما نملي لهم ليزدادوا إثماً»… هل أعدّ تأخّر العقوبة على ذنبي رضا من الله، أم إمهالاً يدعوني للتوبة؟"}, {"lbl": "الآيتان ١٧٩ – ١٨٠", "q": "مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ ﴿١٧٩﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١٨٠﴾", "w": [["ليذر", "ليترك."], ["الخبيث", "من خبثت نفسه بالشرك والمعاصي."], ["الطيب", "من طهرت نفسه بالإيمان والعمل الصالح."], ["الغيب", "ما غاب فلم يُدرك بالحواس."], ["يجتبي", "يختار ويصطفي."], ["يبخلون", "يمنعون ويضنّون."], ["سيُطوّقون", "يُجعل طوقاً في عنق أحدهم."]], "m": "أخبر الله أنه ليس من شأنه أن يترك المؤمنين على ما هم عليه، فيهم الصادق في إيمانه والكاذب وهو المنافق، بل لا بد من الابتلاء بالتكاليف، الشاقة منها كالجهاد والهجرة، وغير الشاقة من سائر العبادات، حتى يميّز الخبيث من الطيب. ولم يكن من سنته أن يطلع خلقه على الغيب فيميّز المؤمن من المنافق، وإنما يبتلي بالتكاليف فيظهر بها ذلك، إلا أنه قد يجتبي من رسله من يشاء فيطلعه على شيء من الغيب؛ فآمنوا بالله ورسله حق الإيمان، وإن تؤمنوا وتتقوا فلكم أجر عظيم. ثم أخبر عن خطأ البخلاء الذين يظنون أن بخلهم بما آتاهم الله من فضله خير لهم، بل هو شرّ لهم لأمرين: ما يلحقهم في الدنيا من معرّة البخل وآثاره السيئة على النفس، وأن الله سيعذبهم به فيجعله طوقاً في أعناقهم يوم القيامة، وكما جاء في الحديث: يُمثَّل له شجاعاً أقرع يطوّقه ويقول: «أنا مالك، أنا كنزك». وما يبخلون به هو مال الله، ولله ميراث السموات والأرض، والله بما تعملون خبير.", "h": ["من حِكم التكليف إظهار المؤمن الصادق من المؤمن الكاذب.", "استئثار الرب تعالى بعلم الغيب دون خلقه، إلا ما يطلع عليه رسله لحكمة اقتضت ذلك.", "ثمن الجنة الإيمان والتقوى.", "البخل بالمال شرّ لصاحبه، وليس بخير له كما يظن البخلاء.", "من أوتي مالاً ومنع حق الله فيه عُذّب به يوم القيامة."], "k": "ما الذي أمسكه بيدي وأظنه خيراً لي، وهو في الحقيقة «مال الله» الذي سيرثه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 62;
insert into public.tdb_cards(topic, i, body) select 62, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧٢ – ١٧٥", "q": "ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ ﴿١٧٢﴾ ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴿١٧٣﴾ فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ ﴿١٧٤﴾ إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٧٥﴾", "w": [["استجابوا", "أجابوا الدعوة وقبلوا الأمر."], ["القرح", "ألم الجراحات."], ["أحسنوا", "أتوا بأعمالهم وأقوالهم وفق الشرع، وأحسنوا إلى غيرهم."], ["اتقوا", "اتقوا ربهم فلم يشركوا به ولم يعصوه فيما أمرهم أو نهاهم."], ["حسبنا الله", "يكفينا الله ما أرادونا به من الأذى."], ["ونعم الوكيل", "نعم الوكيل الله، نَكِل إليه أمورنا ونفوّضها إليه."], ["فانقلبوا", "رجعوا من حمراء الأسد إلى المدينة."], ["أولياءه", "أهل طاعته والاستجابة له فيما يدعوهم إليه من الشر والفساد."]], "m": "الآيات الأربع في المؤمنين الذين حضروا أحداً يوم السبت، وخرجوا في طلب أبي سفيان يوم الأحد مع نبيهم ﷺ؛ إذ رأى أن يرفع معنويات أصحابه ويُرهب أعداءه، فأمر مؤذناً يؤذّن بالخروج، فاستجابوا وفيهم الجريح، حتى إن أخوين جريحين كان أحدهما يحمل أخاه، حتى انتهوا إلى حمراء الأسد، وألقى الله الرعب في قلب أبي سفيان فارتحل إلى مكة. «الذين استجابوا لله والرسول من بعد ما أصابهم القرح، للذين أحسنوا منهم واتقوا أجر عظيم»، وهو الجنة. «الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم»: القائلون نفر من عبد القيس مرّوا بأبي سفيان وهو عازم على العودة إلى المدينة، فقال لهم: أخبروا محمداً وأصحابه أني جامع جيوشي وقادم عليهم، فلما بلغهم ذلك زادهم إيماناً، وقالوا: حسبنا الله، يكفينا شرهم، ونعم الوكيل. فرجعوا سالمين في نعمة الإيمان والنصر، وفضل إذ أصابوا تجارة في عودتهم، لم يمسسهم سوء، واتبعوا رضوان الله بالاستجابة، والله ذو فضل عظيم. ثم قال: «إنما ذلكم الشيطان يخوّف أولياءه»، أي الناطق على لسان أولئك النفر يخوّفكم من أوليائه أبي سفيان وجمعه، فلا تخافوهم وخافوني إن كنتم مؤمنين، وكذلك فعلوا.", "h": ["فضل الإحسان والتقوى، وأنهما مفتاح كل خير.", "فضل أصحاب رسول الله ﷺ على غيرهم، وكرامتهم على ربهم.", "فضل كلمة «حسبنا الله ونعم الوكيل»، قالها رسول الله ﷺ، وقالها إبراهيم ﵇ من قبل.", "بيان أن الشيطان يخوّف المؤمنين من أوليائه، فعلى المؤمنين ألا يخافوا غير ربهم، فيطيعونه ويعبدونه ويتوكلون عليه، وهو حسبهم ونعم الوكيل."], "k": "ما الذي يخيفني هذه الأيام؟ هل أقول عنده من قلبي: «حسبنا الله ونعم الوكيل»؟"}, {"lbl": "الآيات ١٧٦ – ١٧٨", "q": "وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ ﴿١٧٦﴾ إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٧٧﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ ﴿١٧٨﴾", "w": [["ولا يحزنك", "الحزن: غمّ يصيب النفس لرؤية أو سماع ما يسوؤها."], ["الكفر", "تكذيب الله ورسوله فيما جاء به الرسول وأخبر به."], ["يسارعون", "يبادرون."], ["اشتروا الكفر بالإيمان", "اعتاضوا الكفر عن الإيمان."], ["إثماً", "الإثم: كل ضارّ قبيح، ورأسه الكفر والشرك."]], "m": "كشفت أحداث أحد النفاق مكشوفاً لا ستار عليه، فحصل من ذلك ألم شديد لرسول الله ﷺ والمؤمنين، فقال له ربه: لا يحزنك مسارعة هؤلاء المنافقين في الكفر، وقال «في الكفر» ولم يقل «إلى الكفر» إشارة إلى أنهم ما خرجوا منه، إذ كان إسلامهم نفاقاً. إنهم لن يضرّوا الله شيئاً، والله يريد ألا يجعل لهم نصيباً من نعيم الآخرة، فتركهم في كفرهم، ولهم عذاب عظيم. ثم حكم على الذين يرتدّون فيبيعون الإيمان بالكفر بأنهم لن يضرّوا الله شيئاً، ولهم عذاب أليم في النار. ثم أبطل ظنّ الكافرين أن إمهال الله لهم وإطالة أعمارهم خير لهم، بل هو شرّ؛ إذ كلما تأخروا يوماً اكتسبوا فيه إثماً، فيعظم ذنبهم بقدر ما تطول حياتهم، ولهم عذاب مهين، يناسب ما كانوا عليه من كبر وعلوّ وفساد.", "h": ["لا ينبغي للمؤمن أن يحزنه كفر كافر ولا فسق فاسق؛ لأن ذلك لا يضرّ الله شيئاً، وسيجزي الله الكافر والفاسق بعدله.", "لا ينبغي للعبد أن يغرّه إمهال الله له، وعليه أن يبادر بالتوبة من كل ذنب؛ إذ ليس هناك إهمال وإنما هو إمهال.", "الموت للعبد خير من الحياة؛ لأنه إن كان صالحاً فالآخرة خير له من الدنيا، وإن كان غير صالح فالموت خير له حتى لا يزداد إثماً فيوبق بكثرة ذنوبه."], "k": "«إنما نملي لهم ليزدادوا إثماً»… هل أعدّ تأخّر العقوبة على ذنبي رضا من الله، أم إمهالاً يدعوني للتوبة؟"}, {"lbl": "الآيتان ١٧٩ – ١٨٠", "q": "مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ ﴿١٧٩﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١٨٠﴾", "w": [["ليذر", "ليترك."], ["الخبيث", "من خبثت نفسه بالشرك والمعاصي."], ["الطيب", "من طهرت نفسه بالإيمان والعمل الصالح."], ["الغيب", "ما غاب فلم يُدرك بالحواس."], ["يجتبي", "يختار ويصطفي."], ["يبخلون", "يمنعون ويضنّون."], ["سيُطوّقون", "يُجعل طوقاً في عنق أحدهم."]], "m": "أخبر الله أنه ليس من شأنه أن يترك المؤمنين على ما هم عليه، فيهم الصادق في إيمانه والكاذب وهو المنافق، بل لا بد من الابتلاء بالتكاليف، الشاقة منها كالجهاد والهجرة، وغير الشاقة من سائر العبادات، حتى يميّز الخبيث من الطيب. ولم يكن من سنته أن يطلع خلقه على الغيب فيميّز المؤمن من المنافق، وإنما يبتلي بالتكاليف فيظهر بها ذلك، إلا أنه قد يجتبي من رسله من يشاء فيطلعه على شيء من الغيب؛ فآمنوا بالله ورسله حق الإيمان، وإن تؤمنوا وتتقوا فلكم أجر عظيم. ثم أخبر عن خطأ البخلاء الذين يظنون أن بخلهم بما آتاهم الله من فضله خير لهم، بل هو شرّ لهم لأمرين: ما يلحقهم في الدنيا من معرّة البخل وآثاره السيئة على النفس، وأن الله سيعذبهم به فيجعله طوقاً في أعناقهم يوم القيامة، وكما جاء في الحديث: يُمثَّل له شجاعاً أقرع يطوّقه ويقول: «أنا مالك، أنا كنزك». وما يبخلون به هو مال الله، ولله ميراث السموات والأرض، والله بما تعملون خبير.", "h": ["من حِكم التكليف إظهار المؤمن الصادق من المؤمن الكاذب.", "استئثار الرب تعالى بعلم الغيب دون خلقه، إلا ما يطلع عليه رسله لحكمة اقتضت ذلك.", "ثمن الجنة الإيمان والتقوى.", "البخل بالمال شرّ لصاحبه، وليس بخير له كما يظن البخلاء.", "من أوتي مالاً ومنع حق الله فيه عُذّب به يوم القيامة."], "k": "ما الذي أمسكه بيدي وأظنه خيراً لي، وهو في الحقيقة «مال الله» الذي سيرثه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (63, 3, 181, 189, 'سورة آل عمران ١٨١ – ١٨٩', '«إن الله فقير»: مقالة اليهود، وكل نفس ذائقة الموت', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 63) = $j$[{"lbl": "الآيات ١٨١ – ١٨٤", "q": "لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿١٨١﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ ﴿١٨٢﴾ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٨٣﴾ فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ ﴿١٨٤﴾", "w": [["عذاب الحريق", "عذاب النار المحرقة تحرق أجسادهم."], ["ذلك بما قدمت أيديكم", "ذلك العذاب بسبب ما قدّمته أيديكم من الجرائم."], ["عهد إلينا", "أمرنا ووصّانا في كتابنا التوراة."], ["ألا نؤمن لرسول", "ألا نتابعه على ما جاء به ولا نصدّقه في نبوته."], ["بقربان تأكله النار", "القربان: ما يُتقرّب به إلى الله من حيوان وغيره، يوضع في مكان فتنزل عليه نار من السماء فتحرقه."], ["البينات", "الآيات والمعجزات."], ["وبالذي قلتم", "من القربان."], ["فلِمَ قتلتموهم", "استفهام للتوبيخ، وممن قتلوا من الأنبياء زكريا ويحيى ﵉."], ["الزُّبُر", "جمع زبور، وهو الكتاب كصحف إبراهيم."], ["الكتاب المنير", "الواضح البيّن كالتوراة والإنجيل."]], "m": "دخل أبو بكر الصديق رضي الله عنه بيت المدراس واليهود يستمعون لكبير أحبارهم فنحاص، فدعاه إلى الإسلام، فقال فنحاص: إن رباً يستقرض نحن أغنى منه! فغضب أبو بكر فضربه، فشكاه إلى رسول الله ﷺ، فلما سأله قال: إنه قال إن الله فقير ونحن أغنياء، فأنكر اليهودي، فأنزل الله: «لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء، سنكتب ما قالوا وقتلهم الأنبياء بغير حق، ونقول ذوقوا عذاب الحريق»، وذلك بما قدّمت أيديهم، والله ليس بظلّام للعبيد. ثم ذكر دعوى يهودية باطلة: أن الله عهد إليهم ألا يؤمنوا لرسول حتى يأتيهم بقربان تأكله النار، وأنت يا محمد ما أتيتنا بذلك، فردّ عليهم: قد جاءكم رسل من قبلي بالمعجزات وبالذي قلتم، فلِمَ قتلتموهم إن كنتم صادقين؟ ثم عزّى رسوله ﷺ: فإن كذّبوك فلا تحزن، فلست وحدك، فقد كُذّبت رسل كثيرون جاؤوا أقوامهم بالمعجزات والزبر والكتاب المنير، فاصبر.", "h": ["كفر اليهود وسوء أدبهم مع الله تعالى، ومع أنبيائهم، ومع الناس أجمعين.", "تقرير جريمة قتل اليهود للأنبياء، وهي من أبشع الجرائم.", "بيان كذب اليهود في دعواهم أن الله عهد إليهم ألا يؤمنوا لرسول حتى يأتيهم بقربان تأكله النار.", "تعزية الرسول ﷺ وحمله على الصبر والثبات أمام ترّهات اليهود وأباطيلهم."], "k": "غضب أبو بكر لله حين سمع سوء الأدب مع ربه… فهل يتحرك قلبي غيرةً حين يُستهان بحرمات الله؟"}, {"lbl": "الآيتان ١٨٥ – ١٨٦", "q": "كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ﴿١٨٥﴾ ۞لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿١٨٦﴾", "w": [["ذائقة الموت", "ذائقة موت جسدها، أما هي فإنها لا تموت."], ["تُوفَّون", "تُعطَون جزاء أعمالكم خيراً أو شراً وافياً لا نقص فيه."], ["زُحزح", "نُجّي وأُبعد."], ["فاز", "نجا من مرهوبه وهو النار، وظفر بمرغوبه وهو الجنة."], ["متاع الغرور", "المتاع: كل ما يُستمتع به، والغرور: الخداع، فشُبّهت الدنيا بمتاع خادع لا يلبث أن يضمحلّ ويذهب."], ["لتُبلَوُنّ في أموالكم وأنفسكم", "لتُختبرُنّ في أموالكم بأداء الحقوق الواجبة فيها أو بذهابها، وفي أنفسكم بالتكاليف الشاقة كالجهاد والحج، أو بالمرض والموت."], ["أوتوا الكتاب", "اليهود والنصارى."], ["الذين أشركوا", "العرب."], ["من عزم الأمور", "الصبر والتقوى من الأمور الواجبة التي هي عزائم، ليس فيها رخص."]], "m": "ما زال السياق في تعزية الرسول ﷺ وأصحابه، وفي هذه الآية أعظم تسلية؛ إذ أخبر أن كل نفس، مهما علت أو سفلت، ذائقة الموت لا محالة، وأن الدنيا ليست دار جزاء وإنما دار كسب وعمل، ولذا قد يُجرم فيها المجرمون ولا ينالهم مكروه، ويُحسن المحسنون ولا ينالهم محبوب، وإنما تُوفَّون أجوركم يوم القيامة. فمن نُجّي من النار وأُدخل الجنة فقد فاز، وما الحياة الدنيا بكل ما فيها إلا متاع زائل يغرّ ببهرجه ثم يذهب. ثم أخبر رسوله والمؤمنين أنهم مختبرون لا محالة: في أموالهم بالجوائح والواجبات، وفي أنفسهم بالمرض والموت والتكاليف الشاقة، وأنهم سيسمعون من أهل الكتاب والمشركين أذى كثيراً، كقول فنحاص: الله فقير، وقول النصارى: المسيح ابن الله، وقول المشركين في آلهتهم. ثم حثّهم على الصبر والتقوى، فإنهما من عزم الأمور، من باب الفرض والوجوب لا من باب الندب والاستحباب.", "h": ["ليست الدار الدنيا بدار جزاء، وإنما هي دار عمل.", "تعريف الفوز الحق، وهو الزحزحة عن النار ودخول الجنة.", "بيان حقيقة هذه الحياة، وأنها كمتاع خادع لا يلبث أن يتلاشى ويضمحل.", "الابتلاء ضروري، فيجب الصبر والتقوى؛ فإنها من عزائم الأمور لا من رخصها."], "k": "«فمن زُحزح عن النار وأُدخل الجنة فقد فاز»… هل مقياس الفوز عندي هو مقياس القرآن؟"}, {"lbl": "الآيات ١٨٧ – ١٨٩", "q": "وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ ﴿١٨٧﴾ لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٨٨﴾ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١٨٩﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["الكتمان", "إخفاء الشيء وجحوده حتى لا يُرى ولا يُعلم."], ["فنبذوه وراء ظهورهم", "ألقوه وطرحوه ولم يلتفتوا إليه، وهو ما أُخذ عليهم العهد فيه من الإيمان بمحمد ﷺ وبما جاء به."], ["واشتروا به ثمناً قليلاً", "اعتاضوا عنه حطام الدنيا ومتاعها الزائل؛ إبقاءً على منافعهم الدنيوية."], ["أن يُحمدوا بما لم يفعلوا", "أن يُثنى عليهم ويُذكروا بخير، وهم لم يفعلوا ما يوجب ذلك."], ["بمفازة من العذاب", "بمنجاة من العذاب في الدنيا، ولهم في الآخرة عذاب أليم."]], "m": "ما زال السياق في اليهود، فقال الله لنبيه ﷺ: واذكر لهم إذ أخذ الله ميثاق الذين أوتوا الكتاب، أخذ على علمائهم العهد المؤكد أن يبيّنوا للناس نعوت النبي ﷺ في كتابهم، وأن يؤمنوا به ويتابعوه، ولكنهم كتموه ونبذوه وراء ظهورهم، واستبدلوا به ثمناً قليلاً من الجاه والمنصب والمال، فبئس ما يشترون. ثم قال: لا تحسبنّ الذين يفرحون بما أتوا من الشر والفساد بتحريف كلام الله وتغيير شرائعه، وهم مع ذلك يحبون أن يحمدهم الناس ويثنوا عليهم بما لم يفعلوا من الخير، فلا تحسبنّهم بمنجاة من العذاب، ولهم عذاب أليم. ثم أخبر أن له ملك السموات والأرض، وأنه على كل شيء قدير، فدلّ بذلك على قدرته على الانتقام منهم وإنجاز وعيده لهم.", "h": ["أخذ الله الميثاق على علماء أهل الكتاب ببيان الحق يتناول علماء الإسلام، فعليهم أن يبثّوا الحق ويجهروا به، ويحرم عليهم كتمانه أو تأويله إرضاءً للناس ليحوزوا مكسباً دنيوياً مالاً أو جاهاً أو سلطاناً.", "لا يجوز للمسلم أن يحب أن يُحمد بما لم يفعل من الخير والمعروف، بل من الكمال ألا يرغب في مدح الناس وثنائهم وهو فاعل لما يستوجب ذلك، فكيف بمن لم يفعل ثم يحب أن يُحمد، بل بمن يفعل الشر ويحب أن يُحمد عليه؟", "ملك الله تعالى لكل شيء وقدرته على كل شيء توجب الخوف منه والرغبة إليه، وأكثر الناس عن هذا غافلون."], "k": "هل أنتظر الثناء على ما أفعل؟ وهل أفرح أحياناً بمدحٍ على ما لم أفعله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 63;
insert into public.tdb_cards(topic, i, body) select 63, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٨١ – ١٨٤", "q": "لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿١٨١﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ ﴿١٨٢﴾ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٨٣﴾ فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ ﴿١٨٤﴾", "w": [["عذاب الحريق", "عذاب النار المحرقة تحرق أجسادهم."], ["ذلك بما قدمت أيديكم", "ذلك العذاب بسبب ما قدّمته أيديكم من الجرائم."], ["عهد إلينا", "أمرنا ووصّانا في كتابنا التوراة."], ["ألا نؤمن لرسول", "ألا نتابعه على ما جاء به ولا نصدّقه في نبوته."], ["بقربان تأكله النار", "القربان: ما يُتقرّب به إلى الله من حيوان وغيره، يوضع في مكان فتنزل عليه نار من السماء فتحرقه."], ["البينات", "الآيات والمعجزات."], ["وبالذي قلتم", "من القربان."], ["فلِمَ قتلتموهم", "استفهام للتوبيخ، وممن قتلوا من الأنبياء زكريا ويحيى ﵉."], ["الزُّبُر", "جمع زبور، وهو الكتاب كصحف إبراهيم."], ["الكتاب المنير", "الواضح البيّن كالتوراة والإنجيل."]], "m": "دخل أبو بكر الصديق رضي الله عنه بيت المدراس واليهود يستمعون لكبير أحبارهم فنحاص، فدعاه إلى الإسلام، فقال فنحاص: إن رباً يستقرض نحن أغنى منه! فغضب أبو بكر فضربه، فشكاه إلى رسول الله ﷺ، فلما سأله قال: إنه قال إن الله فقير ونحن أغنياء، فأنكر اليهودي، فأنزل الله: «لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء، سنكتب ما قالوا وقتلهم الأنبياء بغير حق، ونقول ذوقوا عذاب الحريق»، وذلك بما قدّمت أيديهم، والله ليس بظلّام للعبيد. ثم ذكر دعوى يهودية باطلة: أن الله عهد إليهم ألا يؤمنوا لرسول حتى يأتيهم بقربان تأكله النار، وأنت يا محمد ما أتيتنا بذلك، فردّ عليهم: قد جاءكم رسل من قبلي بالمعجزات وبالذي قلتم، فلِمَ قتلتموهم إن كنتم صادقين؟ ثم عزّى رسوله ﷺ: فإن كذّبوك فلا تحزن، فلست وحدك، فقد كُذّبت رسل كثيرون جاؤوا أقوامهم بالمعجزات والزبر والكتاب المنير، فاصبر.", "h": ["كفر اليهود وسوء أدبهم مع الله تعالى، ومع أنبيائهم، ومع الناس أجمعين.", "تقرير جريمة قتل اليهود للأنبياء، وهي من أبشع الجرائم.", "بيان كذب اليهود في دعواهم أن الله عهد إليهم ألا يؤمنوا لرسول حتى يأتيهم بقربان تأكله النار.", "تعزية الرسول ﷺ وحمله على الصبر والثبات أمام ترّهات اليهود وأباطيلهم."], "k": "غضب أبو بكر لله حين سمع سوء الأدب مع ربه… فهل يتحرك قلبي غيرةً حين يُستهان بحرمات الله؟"}, {"lbl": "الآيتان ١٨٥ – ١٨٦", "q": "كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ﴿١٨٥﴾ ۞لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿١٨٦﴾", "w": [["ذائقة الموت", "ذائقة موت جسدها، أما هي فإنها لا تموت."], ["تُوفَّون", "تُعطَون جزاء أعمالكم خيراً أو شراً وافياً لا نقص فيه."], ["زُحزح", "نُجّي وأُبعد."], ["فاز", "نجا من مرهوبه وهو النار، وظفر بمرغوبه وهو الجنة."], ["متاع الغرور", "المتاع: كل ما يُستمتع به، والغرور: الخداع، فشُبّهت الدنيا بمتاع خادع لا يلبث أن يضمحلّ ويذهب."], ["لتُبلَوُنّ في أموالكم وأنفسكم", "لتُختبرُنّ في أموالكم بأداء الحقوق الواجبة فيها أو بذهابها، وفي أنفسكم بالتكاليف الشاقة كالجهاد والحج، أو بالمرض والموت."], ["أوتوا الكتاب", "اليهود والنصارى."], ["الذين أشركوا", "العرب."], ["من عزم الأمور", "الصبر والتقوى من الأمور الواجبة التي هي عزائم، ليس فيها رخص."]], "m": "ما زال السياق في تعزية الرسول ﷺ وأصحابه، وفي هذه الآية أعظم تسلية؛ إذ أخبر أن كل نفس، مهما علت أو سفلت، ذائقة الموت لا محالة، وأن الدنيا ليست دار جزاء وإنما دار كسب وعمل، ولذا قد يُجرم فيها المجرمون ولا ينالهم مكروه، ويُحسن المحسنون ولا ينالهم محبوب، وإنما تُوفَّون أجوركم يوم القيامة. فمن نُجّي من النار وأُدخل الجنة فقد فاز، وما الحياة الدنيا بكل ما فيها إلا متاع زائل يغرّ ببهرجه ثم يذهب. ثم أخبر رسوله والمؤمنين أنهم مختبرون لا محالة: في أموالهم بالجوائح والواجبات، وفي أنفسهم بالمرض والموت والتكاليف الشاقة، وأنهم سيسمعون من أهل الكتاب والمشركين أذى كثيراً، كقول فنحاص: الله فقير، وقول النصارى: المسيح ابن الله، وقول المشركين في آلهتهم. ثم حثّهم على الصبر والتقوى، فإنهما من عزم الأمور، من باب الفرض والوجوب لا من باب الندب والاستحباب.", "h": ["ليست الدار الدنيا بدار جزاء، وإنما هي دار عمل.", "تعريف الفوز الحق، وهو الزحزحة عن النار ودخول الجنة.", "بيان حقيقة هذه الحياة، وأنها كمتاع خادع لا يلبث أن يتلاشى ويضمحل.", "الابتلاء ضروري، فيجب الصبر والتقوى؛ فإنها من عزائم الأمور لا من رخصها."], "k": "«فمن زُحزح عن النار وأُدخل الجنة فقد فاز»… هل مقياس الفوز عندي هو مقياس القرآن؟"}, {"lbl": "الآيات ١٨٧ – ١٨٩", "q": "وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ ﴿١٨٧﴾ لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٨٨﴾ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١٨٩﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["الكتمان", "إخفاء الشيء وجحوده حتى لا يُرى ولا يُعلم."], ["فنبذوه وراء ظهورهم", "ألقوه وطرحوه ولم يلتفتوا إليه، وهو ما أُخذ عليهم العهد فيه من الإيمان بمحمد ﷺ وبما جاء به."], ["واشتروا به ثمناً قليلاً", "اعتاضوا عنه حطام الدنيا ومتاعها الزائل؛ إبقاءً على منافعهم الدنيوية."], ["أن يُحمدوا بما لم يفعلوا", "أن يُثنى عليهم ويُذكروا بخير، وهم لم يفعلوا ما يوجب ذلك."], ["بمفازة من العذاب", "بمنجاة من العذاب في الدنيا، ولهم في الآخرة عذاب أليم."]], "m": "ما زال السياق في اليهود، فقال الله لنبيه ﷺ: واذكر لهم إذ أخذ الله ميثاق الذين أوتوا الكتاب، أخذ على علمائهم العهد المؤكد أن يبيّنوا للناس نعوت النبي ﷺ في كتابهم، وأن يؤمنوا به ويتابعوه، ولكنهم كتموه ونبذوه وراء ظهورهم، واستبدلوا به ثمناً قليلاً من الجاه والمنصب والمال، فبئس ما يشترون. ثم قال: لا تحسبنّ الذين يفرحون بما أتوا من الشر والفساد بتحريف كلام الله وتغيير شرائعه، وهم مع ذلك يحبون أن يحمدهم الناس ويثنوا عليهم بما لم يفعلوا من الخير، فلا تحسبنّهم بمنجاة من العذاب، ولهم عذاب أليم. ثم أخبر أن له ملك السموات والأرض، وأنه على كل شيء قدير، فدلّ بذلك على قدرته على الانتقام منهم وإنجاز وعيده لهم.", "h": ["أخذ الله الميثاق على علماء أهل الكتاب ببيان الحق يتناول علماء الإسلام، فعليهم أن يبثّوا الحق ويجهروا به، ويحرم عليهم كتمانه أو تأويله إرضاءً للناس ليحوزوا مكسباً دنيوياً مالاً أو جاهاً أو سلطاناً.", "لا يجوز للمسلم أن يحب أن يُحمد بما لم يفعل من الخير والمعروف، بل من الكمال ألا يرغب في مدح الناس وثنائهم وهو فاعل لما يستوجب ذلك، فكيف بمن لم يفعل ثم يحب أن يُحمد، بل بمن يفعل الشر ويحب أن يُحمد عليه؟", "ملك الله تعالى لكل شيء وقدرته على كل شيء توجب الخوف منه والرغبة إليه، وأكثر الناس عن هذا غافلون."], "k": "هل أنتظر الثناء على ما أفعل؟ وهل أفرح أحياناً بمدحٍ على ما لم أفعله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (64, 3, 190, 200, 'سورة آل عمران ١٩٠ – ٢٠٠', 'أولو الألباب ودعاؤهم، وختام آل عمران: اصبروا وصابروا ورابطوا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 64) = $j$[{"lbl": "الآيات ١٩٠ – ١٩٥", "q": "إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ ﴿١٩٠﴾ ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ﴿١٩١﴾ رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ ﴿١٩٢﴾ رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ ﴿١٩٣﴾ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ ﴿١٩٤﴾ فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ ﴿١٩٥﴾", "w": [["لآيات", "دلائل واضحة على وجود الله تعالى وقدرته وعلمه وحكمته."], ["لأولي الألباب", "أصحاب العقول التي تُدرك بها الأشياء وتُفهم بها الأدلة."], ["باطلاً", "لا لشيء مقصود منه، وإنما من باب اللعب."], ["سبحانك", "تنزيهاً لك عن العبث واللعب، وعن الشريك والولد."], ["فقنا عذاب النار", "أجرنا واحفظنا من عذاب النار بتوفيقك لنا للأعمال الصالحة وتجنيبنا الأعمال الفاسدة."], ["أخزيته", "أذللته وأشقيته."], ["كفّر عنا", "استر وامحُ."], ["الأبرار", "جمع برّ أو بارّ، وهم المتمسكون بالشريعة."], ["على رسلك", "على ألسنة رسلك من النصر والتأييد."], ["الميعاد", "الوعد."], ["هاجروا", "تركوا بلادهم وديارهم وأموالهم وأهليهم فراراً بدينهم."], ["أوذوا في سبيلي", "آذاهم المشركون من أجل الإيمان بي وبرسولي وطاعتنا."]], "m": "لما قال اليهود مقالتهم السيئة، وحرّفوا الكتاب ويحبون أن يُحمدوا على باطلهم، دلّ ذلك على عمى في بصائرهم، فذكر الله من الآيات الكونية ما يدل على غناه وافتقار عباده إليه وعلى ربوبيته وتدبيره، ولا يدرك ذلك إلا أرباب العقول: «إن في خلق السموات والأرض واختلاف الليل والنهار لآيات لأولي الألباب». ثم وصفهم: يذكرون الله قياماً وقعوداً وعلى جنوبهم، في الصلاة وخارجها، ويتفكرون في خلق السموات والأرض وإبداعهما، فلا يلبثون أن يقولوا: ربنا ما خلقت هذا باطلاً، بل خلقته لحِكم عالية، لتُذكر وتُشكر، فتكرم الشاكرين في دار كرامتك، وتهين الكافرين في دار عذابك، سبحانك فقنا عذاب النار. ربنا إنك من تدخل النار فقد أخزيته، وما للظالمين، وهم الكافرون، من أنصار. ربنا إننا سمعنا منادياً، هو القرآن والرسول ﷺ، ينادي للإيمان فآمنّا، فتوسّلوا بإيمانهم طالبين مغفرة ذنوبهم ووفاتهم مع الأبرار، ثم سألوه أن يعطيهم ما وعدهم على ألسنة رسله من النصر والتمكين في الدنيا، وألا يخزيهم يوم القيامة. فاستجاب لهم: إني لا أضيع عمل عامل منكم من ذكر أو أنثى، بعضكم من بعض فلا معنى للتفرقة بينكم، وذكر من أعمالهم: الهجرة، والإخراج من الديار، والأذى في سبيله، والقتال والقتل، ووعدهم بتكفير سيئاتهم وإدخالهم الجنات، ثواباً من عند الله، والله عنده حسن الثواب.", "h": ["وجوب التفكر في خلق السموات والأرض للحصول على المزيد من الإيمان والإيقان.", "استحباب تلاوة هذه الآيات، من «إن في خلق السموات» إلى آخر السورة، عند القيام للتهجد آخر الليل، لثبوت ذلك في الصحيح عنه ﷺ.", "استحباب ذكر الله في كل حال، من قيام أو قعود أو اضطجاع.", "استحباب التعوّذ من النار، بل وجوبه ولو مرة في العمر.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "فضل الهجرة والجهاد في سبيل الله.", "المساواة بين المؤمنين والمؤمنات في العمل والجزاء.", "استحباب الوفاة بين الأبرار، وهم أهل الطاعة لله ولرسوله، وذلك بالحياة معهم والعيش بينهم، لتكون الوفاة بإذن الله معهم."], "k": "متى آخر مرة نظرت إلى السماء متفكراً وقلت: «ربنا ما خلقت هذا باطلاً»؟"}, {"lbl": "الآيات ١٩٦ – ٢٠٠", "q": "لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ ﴿١٩٦﴾ مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٩٧﴾ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ ﴿١٩٨﴾ وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَـٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٩٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٢٠٠﴾", "w": [["لا يغرّنك", "لا يكن منك اغترار، والمخاطب الرسول ﷺ والمراد أصحابه."], ["تقلّب الذين كفروا في البلاد", "تصرّفهم فيها بالتجارة والزراعة والأموال والمآكل."], ["متاع قليل", "تصرّفهم ذلك متاع قليل يتمتعون به أعواماً وينتهي."], ["ثم مأواهم جهنم", "مآلهم بعد التمتع القليل إلى جهنم يأوون إليها فيخلدون."], ["نُزُلاً من عند الله", "النُّزُل: ما يُعدّ للضيف من قِرى: طعام وشراب وفراش."], ["الأبرار", "جمع بارّ، وهو المطيع لله ولرسوله الصادق في طاعته."], ["وما أنزل إليكم", "القرآن والسنة، وما أنزل إليهم: التوراة والإنجيل."], ["خاشعين لله", "مطيعين مخبتين له عز وجل."], ["لا يشترون بآيات الله ثمناً قليلاً", "لا يجحدون أحكام الله وما أُمروا ببيانه للناس مقابل منافع تحصل لهم."], ["اصبروا وصابروا", "الصبر: حبس النفس على طاعة الله ورسوله، والمصابرة: الثبات والصمود أمام العدو."], ["ورابطوا", "المرابطة: لزوم الثغور منعاً للعدو من التسرّب إلى ديار المسلمين."], ["تفلحون", "تفوزون بالظفر بالمرغوب، والسلامة من المرهوب في الدنيا والآخرة."]], "m": "ينهى الله دعاة الحق من هذه الأمة، في شخص نبيهم ﷺ، أن يخدعهم ما يتصرّف فيه أهل الكفر من مكاسب وأرباح ومطاعم ومراكب، فيظنوا أنهم على هدى أو أن الله راضٍ عنهم؛ لا، إنما هو متاع في الدنيا قليل، ثم يُردّون إلى جهنم، وبئس المهاد. ثم ذكر مآل المؤمنين، وهو خير مآل: جنات تجري من تحتها الأنهار خالدين فيها، نُزُلاً من عند الله، وما عند الله خير للأبرار من الدنيا وما فيها، فلا يضرّهم أن يكونوا فقراء وأهل الكفر أغنياء. ثم ردّ على بعض المنافقين الذين أنكروا صلاة النبي ﷺ والمؤمنين على النجاشي بعد موته، فقالوا: يصلّون على رجل مات في غير ديارهم وعلى غير ملتهم! فقال: وإن من أهل الكتاب لمن يؤمن بالله وما أنزل إليكم وما أنزل إليهم، خاشعين لله، لا يشترون بآيات الله ثمناً قليلاً كسائر اليهود والنصارى، كعبد الله بن سلام من اليهود وأصحمة النجاشي من النصارى، وكل من أسلم منهم، أولئك لهم أجرهم عند ربهم. ثم خُتمت السورة بنصيحة غالية للأمة: اصبروا على الطاعات والشدائد، وصابروا أعداءكم حتى يستسلموا، ورابطوا في الثغور مرهبين عدوكم، واتقوا الله لعلكم تفلحون.", "h": ["تنبيه المؤمنين وتحذيرهم من الاغترار بما يكون عليه الكافرون من سعة الرزق وهناءة العيش؛ فإن ذلك لم يكن عن رضى الله عنهم، وإنما هو متاع حصل لهم بحسب سنة الله في الكسب والعمل.", "ما أُعدّ لأهل الإيمان والتقوى، وهم الأبرار، من نعيم مقيم في جوار ربهم خير من الدنيا وما فيها.", "شرف مؤمني أهل الكتاب وبشارة القرآن لهم بالجنة، وعلى رأسهم عبد الله بن سلام وأصحمة النجاشي.", "وجوب الصبر والمصابرة والتقوى والمرابطة للحصول على الفلاح، الذي هو الفوز بالمرغوب والسلامة من المرهوب في الدنيا والآخرة."], "k": "«اصبروا وصابروا ورابطوا»… على أي طاعة أحتاج أن «أرابط» هذه الأيام ولا أتركها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 64;
insert into public.tdb_cards(topic, i, body) select 64, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩٠ – ١٩٥", "q": "إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ ﴿١٩٠﴾ ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ﴿١٩١﴾ رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ ﴿١٩٢﴾ رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ ﴿١٩٣﴾ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ ﴿١٩٤﴾ فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ ﴿١٩٥﴾", "w": [["لآيات", "دلائل واضحة على وجود الله تعالى وقدرته وعلمه وحكمته."], ["لأولي الألباب", "أصحاب العقول التي تُدرك بها الأشياء وتُفهم بها الأدلة."], ["باطلاً", "لا لشيء مقصود منه، وإنما من باب اللعب."], ["سبحانك", "تنزيهاً لك عن العبث واللعب، وعن الشريك والولد."], ["فقنا عذاب النار", "أجرنا واحفظنا من عذاب النار بتوفيقك لنا للأعمال الصالحة وتجنيبنا الأعمال الفاسدة."], ["أخزيته", "أذللته وأشقيته."], ["كفّر عنا", "استر وامحُ."], ["الأبرار", "جمع برّ أو بارّ، وهم المتمسكون بالشريعة."], ["على رسلك", "على ألسنة رسلك من النصر والتأييد."], ["الميعاد", "الوعد."], ["هاجروا", "تركوا بلادهم وديارهم وأموالهم وأهليهم فراراً بدينهم."], ["أوذوا في سبيلي", "آذاهم المشركون من أجل الإيمان بي وبرسولي وطاعتنا."]], "m": "لما قال اليهود مقالتهم السيئة، وحرّفوا الكتاب ويحبون أن يُحمدوا على باطلهم، دلّ ذلك على عمى في بصائرهم، فذكر الله من الآيات الكونية ما يدل على غناه وافتقار عباده إليه وعلى ربوبيته وتدبيره، ولا يدرك ذلك إلا أرباب العقول: «إن في خلق السموات والأرض واختلاف الليل والنهار لآيات لأولي الألباب». ثم وصفهم: يذكرون الله قياماً وقعوداً وعلى جنوبهم، في الصلاة وخارجها، ويتفكرون في خلق السموات والأرض وإبداعهما، فلا يلبثون أن يقولوا: ربنا ما خلقت هذا باطلاً، بل خلقته لحِكم عالية، لتُذكر وتُشكر، فتكرم الشاكرين في دار كرامتك، وتهين الكافرين في دار عذابك، سبحانك فقنا عذاب النار. ربنا إنك من تدخل النار فقد أخزيته، وما للظالمين، وهم الكافرون، من أنصار. ربنا إننا سمعنا منادياً، هو القرآن والرسول ﷺ، ينادي للإيمان فآمنّا، فتوسّلوا بإيمانهم طالبين مغفرة ذنوبهم ووفاتهم مع الأبرار، ثم سألوه أن يعطيهم ما وعدهم على ألسنة رسله من النصر والتمكين في الدنيا، وألا يخزيهم يوم القيامة. فاستجاب لهم: إني لا أضيع عمل عامل منكم من ذكر أو أنثى، بعضكم من بعض فلا معنى للتفرقة بينكم، وذكر من أعمالهم: الهجرة، والإخراج من الديار، والأذى في سبيله، والقتال والقتل، ووعدهم بتكفير سيئاتهم وإدخالهم الجنات، ثواباً من عند الله، والله عنده حسن الثواب.", "h": ["وجوب التفكر في خلق السموات والأرض للحصول على المزيد من الإيمان والإيقان.", "استحباب تلاوة هذه الآيات، من «إن في خلق السموات» إلى آخر السورة، عند القيام للتهجد آخر الليل، لثبوت ذلك في الصحيح عنه ﷺ.", "استحباب ذكر الله في كل حال، من قيام أو قعود أو اضطجاع.", "استحباب التعوّذ من النار، بل وجوبه ولو مرة في العمر.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "فضل الهجرة والجهاد في سبيل الله.", "المساواة بين المؤمنين والمؤمنات في العمل والجزاء.", "استحباب الوفاة بين الأبرار، وهم أهل الطاعة لله ولرسوله، وذلك بالحياة معهم والعيش بينهم، لتكون الوفاة بإذن الله معهم."], "k": "متى آخر مرة نظرت إلى السماء متفكراً وقلت: «ربنا ما خلقت هذا باطلاً»؟"}, {"lbl": "الآيات ١٩٦ – ٢٠٠", "q": "لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ ﴿١٩٦﴾ مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٩٧﴾ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ ﴿١٩٨﴾ وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَـٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٩٩﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٢٠٠﴾", "w": [["لا يغرّنك", "لا يكن منك اغترار، والمخاطب الرسول ﷺ والمراد أصحابه."], ["تقلّب الذين كفروا في البلاد", "تصرّفهم فيها بالتجارة والزراعة والأموال والمآكل."], ["متاع قليل", "تصرّفهم ذلك متاع قليل يتمتعون به أعواماً وينتهي."], ["ثم مأواهم جهنم", "مآلهم بعد التمتع القليل إلى جهنم يأوون إليها فيخلدون."], ["نُزُلاً من عند الله", "النُّزُل: ما يُعدّ للضيف من قِرى: طعام وشراب وفراش."], ["الأبرار", "جمع بارّ، وهو المطيع لله ولرسوله الصادق في طاعته."], ["وما أنزل إليكم", "القرآن والسنة، وما أنزل إليهم: التوراة والإنجيل."], ["خاشعين لله", "مطيعين مخبتين له عز وجل."], ["لا يشترون بآيات الله ثمناً قليلاً", "لا يجحدون أحكام الله وما أُمروا ببيانه للناس مقابل منافع تحصل لهم."], ["اصبروا وصابروا", "الصبر: حبس النفس على طاعة الله ورسوله، والمصابرة: الثبات والصمود أمام العدو."], ["ورابطوا", "المرابطة: لزوم الثغور منعاً للعدو من التسرّب إلى ديار المسلمين."], ["تفلحون", "تفوزون بالظفر بالمرغوب، والسلامة من المرهوب في الدنيا والآخرة."]], "m": "ينهى الله دعاة الحق من هذه الأمة، في شخص نبيهم ﷺ، أن يخدعهم ما يتصرّف فيه أهل الكفر من مكاسب وأرباح ومطاعم ومراكب، فيظنوا أنهم على هدى أو أن الله راضٍ عنهم؛ لا، إنما هو متاع في الدنيا قليل، ثم يُردّون إلى جهنم، وبئس المهاد. ثم ذكر مآل المؤمنين، وهو خير مآل: جنات تجري من تحتها الأنهار خالدين فيها، نُزُلاً من عند الله، وما عند الله خير للأبرار من الدنيا وما فيها، فلا يضرّهم أن يكونوا فقراء وأهل الكفر أغنياء. ثم ردّ على بعض المنافقين الذين أنكروا صلاة النبي ﷺ والمؤمنين على النجاشي بعد موته، فقالوا: يصلّون على رجل مات في غير ديارهم وعلى غير ملتهم! فقال: وإن من أهل الكتاب لمن يؤمن بالله وما أنزل إليكم وما أنزل إليهم، خاشعين لله، لا يشترون بآيات الله ثمناً قليلاً كسائر اليهود والنصارى، كعبد الله بن سلام من اليهود وأصحمة النجاشي من النصارى، وكل من أسلم منهم، أولئك لهم أجرهم عند ربهم. ثم خُتمت السورة بنصيحة غالية للأمة: اصبروا على الطاعات والشدائد، وصابروا أعداءكم حتى يستسلموا، ورابطوا في الثغور مرهبين عدوكم، واتقوا الله لعلكم تفلحون.", "h": ["تنبيه المؤمنين وتحذيرهم من الاغترار بما يكون عليه الكافرون من سعة الرزق وهناءة العيش؛ فإن ذلك لم يكن عن رضى الله عنهم، وإنما هو متاع حصل لهم بحسب سنة الله في الكسب والعمل.", "ما أُعدّ لأهل الإيمان والتقوى، وهم الأبرار، من نعيم مقيم في جوار ربهم خير من الدنيا وما فيها.", "شرف مؤمني أهل الكتاب وبشارة القرآن لهم بالجنة، وعلى رأسهم عبد الله بن سلام وأصحمة النجاشي.", "وجوب الصبر والمصابرة والتقوى والمرابطة للحصول على الفلاح، الذي هو الفوز بالمرغوب والسلامة من المرهوب في الدنيا والآخرة."], "k": "«اصبروا وصابروا ورابطوا»… على أي طاعة أحتاج أن «أرابط» هذه الأيام ولا أتركها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (65, 4, 1, 6, 'سورة النساء ١ – ٦', 'افتتاح سورة النساء: تقوى الله، وصلة الأرحام، وحقوق اليتامى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 65) = $j$[{"lbl": "الآية ١", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا ﴿١﴾", "w": [["الناس", "البشر، وواحد الناس من غير لفظه: إنسان."], ["اتقوا ربكم", "خافوه أن يعذبكم، فامتثلوا أمره واجتنبوا نهيه."], ["من نفس واحدة", "هي آدم ﵇."], ["وخلق منها زوجها", "خلق حواء من آدم من ضلعه."], ["وبثّ", "نشر وفرّق في الأرض من آدم وزوجه رجالاً ونساءً كثيرين."], ["تساءلون به", "كقول الرجل لأخيه: أسألك بالله أن تفعل لي كذا."], ["والأرحام", "جمع رحم، والمراد من اتقاء الأرحام صلتها وعدم قطعها."], ["رقيباً", "الرقيب: الحفيظ العليم."]], "m": "ينادي الرب تبارك وتعالى عباده بلفظ عام يشمل مؤمنهم وكافرهم: «يا أيها الناس»، ويأمرهم بتقواه، وهي اتقاء عذابه في الدنيا والآخرة بالإسلام التام إليه ظاهراً وباطناً، واصفاً نفسه بأنه ربهم الذي خلقهم من نفس واحدة هي آدم، وخلق منها زوجها حواء، ونشر منهما في الأرض رجالاً كثيراً ونساءً. ثم كرر الأمر بالتقوى، إذ هي ملاك الأمر، فلا كمال ولا سعادة بدونها: واتقوا الله الذي تساءلون به، فكان أحدكم إذا أراد من أخيه شيئاً قال: أسألك بالله، واتقوا الأرحام أن تقطعوها، فإن في قطعها فساداً كبيراً يصيب حياتكم. وتوعّدهم إن لم يمتثلوا بقوله: «إن الله كان عليكم رقيباً»، مراعياً لأعمالكم محصياً لها، يجزيكم بها.", "h": ["فضل هذه الآية؛ إذ كان النبي ﷺ إذا خطب في حاجة تلا آية آل عمران «اتقوا الله حق تقاته»، وتلا هذه الآية، ثم آية الأحزاب «اتقوا الله وقولوا قولاً سديداً»، ثم يقول: أما بعد، ويذكر حاجته.", "أهمية الأمر بتقوى الله تعالى؛ إذ كُرّرت في آية واحدة مرتين، في أولها وفي آخرها.", "وجوب صلة الأرحام وحرمة قطعها.", "مراعاة الأخوّة البشرية بين الناس واعتبارها في المعاملات."], "k": "«والأرحام»… من الرحم التي قصّرت في صلتها؟ وهل أتصل بها اليوم؟"}, {"lbl": "الآيات ٢ – ٤", "q": "وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا ﴿٢﴾ وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ ﴿٣﴾ وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا ﴿٤﴾", "w": [["اليتامى", "جمع يتيم ذكراً كان أو أنثى، وهو من مات والده وهو غير بالغ الحلم."], ["ولا تتبدّلوا الخبيث بالطيب", "الخبيث: الحرام، والطيب: الحلال، والمراد بهما هنا الرديء والجيد."], ["حُوباً كبيراً", "الحوب: الإثم الكبير العظيم."], ["ألا تقسطوا", "ألا تعدلوا."], ["مثنى وثلاث ورباع", "اثنتين أو ثلاثاً أو أربعاً؛ إذ لا تحل الزيادة على الأربع."], ["أدنى ألا تعولوا", "أقرب ألا تجوروا بترك العدل بين الزوجات."], ["صدقاتهن نِحلة", "جمع صدقة، وهي الصداق والمهر، ونحلة بمعنى فريضة."], ["هنيئاً", "ما يُستلذّ به عند أكله."], ["مريئاً", "ما تحسن عاقبته فلا يُعقب آثاراً سيئة."]], "m": "لما أمر الله بصلة الأرحام وحرّم قطعها، أمر أوصياء اليتامى أن يعطوهم أموالهم إذا بلغوا سنّ الرشد وآنسوا منهم الرشد، ونهاهم أن يستبدلوا أموال اليتامى الجيدة بأموالهم الرديئة، وأن يأكلوا أموال اليتامى مخلوطة مع أموالهم، فإن ذلك إثم عظيم. ثم أرشد أولياء اليتيمات، إن خافوا ألا يعدلوا مع وليّاتهم إذا تزوّجوهن، أن يتزوّجوا ما طاب لهم من النساء غيرهن، اثنتين أو ثلاثاً أو أربعاً كلٌّ بحسب قدرته، فهذا خير من الزواج بالوليّة فيُهضم حقها، وحقها آكد لقرابتها. وإن خاف المؤمن ألا يعدل بين زوجاته فليكتفِ بواحدة، أو بما ملكت يمينه، فذلك أقرب ألا يجور ويظلم. ثم أمر المؤمنين أن يعطوا النساء مهورهن فريضة من الله، فلا يحلّ للزوج ولا لغيره أن يأخذ منها شيئاً إلا برضا الزوجة، فإن طابت نفسها بشيء منه فلا حرج في أكله.", "h": ["كل مال حرام فهو خبيث، وكل حلال فهو طيب.", "لا يحل للرجل أن يستبدل جيداً من مال يتيمه بمال رديء من ماله، كأن يأخذ شاة سمينة ويعطيه هزيلة.", "لا يحل خلط مال اليتيم مع مال الوصي ويؤكلان جميعاً، لما في ذلك من أكل مال اليتيم.", "جواز نكاح أكثر من واحدة إلى أربع مع الأمن من الحيف والجور.", "وجوب مهور النساء، وحرمة الأكل منها بغير طيب نفس صاحبة المهر، سواء في ذلك الزوج أو الأب والأقارب."], "k": "هل أعدل فيمن تحت يدي ورعايتي؟ وهل أعطي كل ذي حق حقه كاملاً؟"}, {"lbl": "الآيتان ٥ – ٦", "q": "وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ﴿٥﴾ وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا ﴿٦﴾", "w": [["ولا تؤتوا", "لا تعطوا."], ["السفهاء", "جمع سفيه، وهو من لا يُحسن التصرف في المال."], ["قياماً", "ما يقوم به الشيء، فالأموال تقوم عليها معايش الناس ومصالحهم الدنيوية والدينية."], ["قولاً معروفاً", "قولاً تطيب به نفسه فلا يغضب ولا يحزن."], ["وابتلوا اليتامى", "اختبروهم لتعرفوا هل أصبحوا يحسنون التصرف في المال."], ["بلغوا النكاح", "سنّ الزواج، وهو البلوغ."], ["آنستم", "أبصرتم الرشد في تصرفاتهم."], ["إسرافاً وبداراً", "الإسراف: الإنفاق في غير الحاجة، والبدار: المبادرة إلى الأكل قبل أن ينتقل المال إلى اليتيم."], ["فليستعفف", "فليكفّ عن الأكل من مال يتيمه."], ["فليأكل بالمعروف", "بقدر الحاجة الضرورية."], ["وكفى بالله حسيباً", "شاهداً."]], "m": "نهى الله المؤمنين أن يعطوا أموالهم، التي هي قوام معاشهم، للسفهاء من امرأة أو ولد أو رجل قام به وصف السفه، وهو قلة البصيرة بالأمور المالية، مخافة أن ينفقوها في غير وجوهها أو يفسدوها بالإسراف ونحوه، وأمرهم أن يرزقوهم فيها ويكسوهم، وقال «فيها» ولم يقل «منها» إشارة إلى أن المال ينبغي أن يُنمّى في تجارة أو صناعة أو زراعة فيبقى رأس المال ويكون الأكل من الربح، وأن يقولوا لهم قولاً معروفاً كالعِدة الحسنة والكلمة الطيبة. ثم أمرهم باختبار اليتامى إذا قاربوا البلوغ، بأن يعطوهم شيئاً من المال ليبيعوا ويشتروا، فإذا وجدوا منهم حسن تصرف دفعوا إليهم أموالهم وأشهدوا عليهم، وكفى بالله حسيباً. ونهاهم أن يأكلوا أموال اليتامى إسرافاً ومبادرةً قبل أن يكبروا، ثم أرشدهم: من كان غنياً فليكفّ عن مال اليتيم، ومن كان فقيراً فليأكل بالمعروف بأن يستقرض منه ثم يردّه بعد الميسرة، وإن احتاج مال اليتيم إلى من يعمل فيه جاز للولي الفقير أن يعمل بأجر، والغني يعمل محتسباً.", "h": ["مشروعية الحجر على السفيه لمصلحته.", "استحباب تنمية الأموال في الأوجه الحلال، لقرينة «وارزقوهم فيها».", "وجوب اختبار السفيه قبل دفع ماله إليه؛ إذ لا يُدفع إليه المال إلا بعد وجود الرشد.", "وجوب الإشهاد على دفع المال إلى اليتيم بعد بلوغه ورشده.", "حرمة أكل مال اليتيم والسفيه مطلقاً.", "الولي على اليتيم إن كان غنياً فلا يأكل من مال اليتيم شيئاً، وإن كان فقيراً استقرض وردّ عند اليسار، وإن احتاج مال اليتيم إلى أجير جاز للولي أن يعمل فيه بأجرة المثل."], "k": "المال «قيام» الحياة… هل أديره بحكمة وأنمّيه في الحلال، أم أبدّده؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 65;
insert into public.tdb_cards(topic, i, body) select 65, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ١", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا ﴿١﴾", "w": [["الناس", "البشر، وواحد الناس من غير لفظه: إنسان."], ["اتقوا ربكم", "خافوه أن يعذبكم، فامتثلوا أمره واجتنبوا نهيه."], ["من نفس واحدة", "هي آدم ﵇."], ["وخلق منها زوجها", "خلق حواء من آدم من ضلعه."], ["وبثّ", "نشر وفرّق في الأرض من آدم وزوجه رجالاً ونساءً كثيرين."], ["تساءلون به", "كقول الرجل لأخيه: أسألك بالله أن تفعل لي كذا."], ["والأرحام", "جمع رحم، والمراد من اتقاء الأرحام صلتها وعدم قطعها."], ["رقيباً", "الرقيب: الحفيظ العليم."]], "m": "ينادي الرب تبارك وتعالى عباده بلفظ عام يشمل مؤمنهم وكافرهم: «يا أيها الناس»، ويأمرهم بتقواه، وهي اتقاء عذابه في الدنيا والآخرة بالإسلام التام إليه ظاهراً وباطناً، واصفاً نفسه بأنه ربهم الذي خلقهم من نفس واحدة هي آدم، وخلق منها زوجها حواء، ونشر منهما في الأرض رجالاً كثيراً ونساءً. ثم كرر الأمر بالتقوى، إذ هي ملاك الأمر، فلا كمال ولا سعادة بدونها: واتقوا الله الذي تساءلون به، فكان أحدكم إذا أراد من أخيه شيئاً قال: أسألك بالله، واتقوا الأرحام أن تقطعوها، فإن في قطعها فساداً كبيراً يصيب حياتكم. وتوعّدهم إن لم يمتثلوا بقوله: «إن الله كان عليكم رقيباً»، مراعياً لأعمالكم محصياً لها، يجزيكم بها.", "h": ["فضل هذه الآية؛ إذ كان النبي ﷺ إذا خطب في حاجة تلا آية آل عمران «اتقوا الله حق تقاته»، وتلا هذه الآية، ثم آية الأحزاب «اتقوا الله وقولوا قولاً سديداً»، ثم يقول: أما بعد، ويذكر حاجته.", "أهمية الأمر بتقوى الله تعالى؛ إذ كُرّرت في آية واحدة مرتين، في أولها وفي آخرها.", "وجوب صلة الأرحام وحرمة قطعها.", "مراعاة الأخوّة البشرية بين الناس واعتبارها في المعاملات."], "k": "«والأرحام»… من الرحم التي قصّرت في صلتها؟ وهل أتصل بها اليوم؟"}, {"lbl": "الآيات ٢ – ٤", "q": "وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا ﴿٢﴾ وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ ﴿٣﴾ وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا ﴿٤﴾", "w": [["اليتامى", "جمع يتيم ذكراً كان أو أنثى، وهو من مات والده وهو غير بالغ الحلم."], ["ولا تتبدّلوا الخبيث بالطيب", "الخبيث: الحرام، والطيب: الحلال، والمراد بهما هنا الرديء والجيد."], ["حُوباً كبيراً", "الحوب: الإثم الكبير العظيم."], ["ألا تقسطوا", "ألا تعدلوا."], ["مثنى وثلاث ورباع", "اثنتين أو ثلاثاً أو أربعاً؛ إذ لا تحل الزيادة على الأربع."], ["أدنى ألا تعولوا", "أقرب ألا تجوروا بترك العدل بين الزوجات."], ["صدقاتهن نِحلة", "جمع صدقة، وهي الصداق والمهر، ونحلة بمعنى فريضة."], ["هنيئاً", "ما يُستلذّ به عند أكله."], ["مريئاً", "ما تحسن عاقبته فلا يُعقب آثاراً سيئة."]], "m": "لما أمر الله بصلة الأرحام وحرّم قطعها، أمر أوصياء اليتامى أن يعطوهم أموالهم إذا بلغوا سنّ الرشد وآنسوا منهم الرشد، ونهاهم أن يستبدلوا أموال اليتامى الجيدة بأموالهم الرديئة، وأن يأكلوا أموال اليتامى مخلوطة مع أموالهم، فإن ذلك إثم عظيم. ثم أرشد أولياء اليتيمات، إن خافوا ألا يعدلوا مع وليّاتهم إذا تزوّجوهن، أن يتزوّجوا ما طاب لهم من النساء غيرهن، اثنتين أو ثلاثاً أو أربعاً كلٌّ بحسب قدرته، فهذا خير من الزواج بالوليّة فيُهضم حقها، وحقها آكد لقرابتها. وإن خاف المؤمن ألا يعدل بين زوجاته فليكتفِ بواحدة، أو بما ملكت يمينه، فذلك أقرب ألا يجور ويظلم. ثم أمر المؤمنين أن يعطوا النساء مهورهن فريضة من الله، فلا يحلّ للزوج ولا لغيره أن يأخذ منها شيئاً إلا برضا الزوجة، فإن طابت نفسها بشيء منه فلا حرج في أكله.", "h": ["كل مال حرام فهو خبيث، وكل حلال فهو طيب.", "لا يحل للرجل أن يستبدل جيداً من مال يتيمه بمال رديء من ماله، كأن يأخذ شاة سمينة ويعطيه هزيلة.", "لا يحل خلط مال اليتيم مع مال الوصي ويؤكلان جميعاً، لما في ذلك من أكل مال اليتيم.", "جواز نكاح أكثر من واحدة إلى أربع مع الأمن من الحيف والجور.", "وجوب مهور النساء، وحرمة الأكل منها بغير طيب نفس صاحبة المهر، سواء في ذلك الزوج أو الأب والأقارب."], "k": "هل أعدل فيمن تحت يدي ورعايتي؟ وهل أعطي كل ذي حق حقه كاملاً؟"}, {"lbl": "الآيتان ٥ – ٦", "q": "وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ﴿٥﴾ وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا ﴿٦﴾", "w": [["ولا تؤتوا", "لا تعطوا."], ["السفهاء", "جمع سفيه، وهو من لا يُحسن التصرف في المال."], ["قياماً", "ما يقوم به الشيء، فالأموال تقوم عليها معايش الناس ومصالحهم الدنيوية والدينية."], ["قولاً معروفاً", "قولاً تطيب به نفسه فلا يغضب ولا يحزن."], ["وابتلوا اليتامى", "اختبروهم لتعرفوا هل أصبحوا يحسنون التصرف في المال."], ["بلغوا النكاح", "سنّ الزواج، وهو البلوغ."], ["آنستم", "أبصرتم الرشد في تصرفاتهم."], ["إسرافاً وبداراً", "الإسراف: الإنفاق في غير الحاجة، والبدار: المبادرة إلى الأكل قبل أن ينتقل المال إلى اليتيم."], ["فليستعفف", "فليكفّ عن الأكل من مال يتيمه."], ["فليأكل بالمعروف", "بقدر الحاجة الضرورية."], ["وكفى بالله حسيباً", "شاهداً."]], "m": "نهى الله المؤمنين أن يعطوا أموالهم، التي هي قوام معاشهم، للسفهاء من امرأة أو ولد أو رجل قام به وصف السفه، وهو قلة البصيرة بالأمور المالية، مخافة أن ينفقوها في غير وجوهها أو يفسدوها بالإسراف ونحوه، وأمرهم أن يرزقوهم فيها ويكسوهم، وقال «فيها» ولم يقل «منها» إشارة إلى أن المال ينبغي أن يُنمّى في تجارة أو صناعة أو زراعة فيبقى رأس المال ويكون الأكل من الربح، وأن يقولوا لهم قولاً معروفاً كالعِدة الحسنة والكلمة الطيبة. ثم أمرهم باختبار اليتامى إذا قاربوا البلوغ، بأن يعطوهم شيئاً من المال ليبيعوا ويشتروا، فإذا وجدوا منهم حسن تصرف دفعوا إليهم أموالهم وأشهدوا عليهم، وكفى بالله حسيباً. ونهاهم أن يأكلوا أموال اليتامى إسرافاً ومبادرةً قبل أن يكبروا، ثم أرشدهم: من كان غنياً فليكفّ عن مال اليتيم، ومن كان فقيراً فليأكل بالمعروف بأن يستقرض منه ثم يردّه بعد الميسرة، وإن احتاج مال اليتيم إلى من يعمل فيه جاز للولي الفقير أن يعمل بأجر، والغني يعمل محتسباً.", "h": ["مشروعية الحجر على السفيه لمصلحته.", "استحباب تنمية الأموال في الأوجه الحلال، لقرينة «وارزقوهم فيها».", "وجوب اختبار السفيه قبل دفع ماله إليه؛ إذ لا يُدفع إليه المال إلا بعد وجود الرشد.", "وجوب الإشهاد على دفع المال إلى اليتيم بعد بلوغه ورشده.", "حرمة أكل مال اليتيم والسفيه مطلقاً.", "الولي على اليتيم إن كان غنياً فلا يأكل من مال اليتيم شيئاً، وإن كان فقيراً استقرض وردّ عند اليسار، وإن احتاج مال اليتيم إلى أجير جاز للولي أن يعمل فيه بأجرة المثل."], "k": "المال «قيام» الحياة… هل أديره بحكمة وأنمّيه في الحلال، أم أبدّده؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (66, 4, 7, 14, 'سورة النساء ٧ – ١٤', 'نصيب الرجال والنساء من الميراث، وتفصيل الفرائض', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 66) = $j$[{"lbl": "الآيات ٧ – ١٠", "q": "لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا ﴿٧﴾ وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ﴿٨﴾ وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا ﴿٩﴾ إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا ﴿١٠﴾", "w": [["نصيب", "الحظ المقدّر في كتاب الله."], ["الوالدان", "الأب والأم."], ["الأقربون", "جمع قريب، وهو هنا الوارث بنسب أو مصاهرة أو ولاء."], ["نصيباً مفروضاً", "قدراً واجباً لازماً."], ["أولو القربى", "أصحاب القرابات الذين لا يرثون لبعدهم عن عمودي النسب."], ["فارزقوهم منه", "أعطوهم شيئاً يرزقونه."], ["قولاً معروفاً", "لا إهانة فيه ولا عتاب ولا تأفيف."], ["وليخش", "الخشية: الخوف في موضع الأمن."], ["قولاً سديداً", "عدلاً صائباً."], ["ظلماً", "بغير حق يخوّل لهم أكل مال اليتيم."], ["وسيصلون سعيراً", "سيدخلون ناراً مستعرة يُشوَون فيها."]], "m": "كان أهل الجاهلية لا يورّثون النساء ولا الأطفال، بحجة أنهم لا يركبون فرساً ولا يحملون كلّاً ولا ينكؤون عدواً، وحدث أن امرأة يقال لها أم كُجّة مات زوجها وترك لها بنتين، فمنعهما أخو الهالك من الإرث، فشكت إلى رسول الله ﷺ، فنزلت: «للرجال نصيب مما ترك الوالدان والأقربون، وللنساء نصيب مما ترك الوالدان والأقربون»، قلّ المال أو كثر، نصيباً مفروضاً لا بد من إعطائه للوارث ذكراً أو أنثى، صغيراً أو كبيراً. ثم ذكر فضيلة غفل عنها المؤمنون: إذا حضر قسمة التركة قريب غير وارث أو يتيم أو مسكين، فمن المعروف أن يُعطَوا منها شيئاً، فإن تعذّر لأن الورثة يتامى صُرفوا بكلمة طيبة. ثم أرشد من يحضر مريضاً على فراش الموت ألا يدعه يحيف في الوصية، بأن يوصي لوارث أو بأكثر من الثلث، فليخشَ على أولاد غيره ما يخشاه على أولاده الضعاف من بعده، وليتّق الله وليقل قولاً سديداً. ثم توعّد من يأكل أموال اليتامى ظلماً بأنهم إنما يأكلون في بطونهم ناراً، باعتبار ما يؤول إليه أمرهم، وسيصلون سعيراً.", "h": ["تقرير مبدأ التوارث في الإسلام.", "استحباب إعطاء من حضر قسمة التركة من قريب أو يتيم أو مسكين، وإن تعذّر إعطاؤهم صُرفوا بالكلمة الطيبة، وفي الحديث: «الكلمة الطيبة صدقة».", "وجوب النصح والإرشاد للمحتضر حتى لا يجور في وصيته عند موته.", "على من يخاف على أطفاله بعد موته أن يحسن إلى أطفال غيره، فإن الله تعالى يكفيه فيهم.", "حرمة أكل مال اليتامى ظلماً، والوعيد الشديد فيه."], "k": "«فليتقوا الله وليقولوا قولاً سديداً»… كيف أحب أن يُعامَل أولادي من بعدي؟ وهل أعامل أبناء غيري كذلك؟"}, {"lbl": "الآية ١١", "q": "يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿١١﴾", "w": [["يوصيكم", "يعهد إليكم."], ["في أولادكم", "في شأن أولادكم، والولد يطلق على الذكر والأنثى."], ["حظ", "الحصة أو النصيب."], ["نساء", "بنات كبيرات أو صغيرات."], ["ثلثا ما ترك", "الثلث واحد من ثلاثة، والثلثان اثنان من ثلاثة."], ["السدس", "واحد من ستة."], ["إن كان له ولد", "ذكراً كان أو أنثى، أو ولد ولد كذلك."], ["فإن كان له إخوة", "اثنان فأكثر."], ["من بعد وصية", "بعد الدَّين ثم الوصية، ويُقسم الباقي على الورثة."], ["لا تدرون", "لا تعلمون."], ["فريضة", "فرض الله ذلك عليكم فريضة."], ["عليماً حكيماً", "عليماً بخلقه وما يصلح لهم، حكيماً في تدبيره لشؤونهم."]], "m": "نزلت هذه الآية والتي بعدها لتفصيل ما أجملته آية «للرجال نصيب». فبيّن الله توارث الأبناء مع الآباء: إذا مات الرجل وترك أولاداً ذكوراً وإناثاً قُسمت التركة للذكر مثل حظ الأنثيين، فلو ترك ولداً وبنتاً وثلاثة دنانير أخذ الولد دينارين والبنت ديناراً. وإن ترك بنتين فأكثر ولا ذكر معهن فلهن الثلثان والباقي للعصبة، وإن ترك بنتاً واحدة فلها النصف والباقي للعصبة. وإن ترك أبويه مع أولاده فلكل واحد من الأبوين السدس، وإن لم يكن له ولد ولا ولد ولد فلأمه الثلث، فإن كان له إخوة اثنان فأكثر حجبوها من الثلث إلى السدس. وكل ذلك بعد قضاء دين الميت وإخراج وصيته إن كانت الثلث فأقل. ثم قال: آباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعاً، فنفّذوا القسمة كما علّمكم الله بلا محاباة، فإنها فريضة من عليم حكيم، فليرضَ العبد بها.", "h": ["أن الله تعالى تولّى قسمة التركات بنفسه، فلا يحل لأحد أن يغيّر منها شيئاً.", "الاثنان يُعتبران جمعاً.", "ولد الولد حكمه حكم الولد نفسه في الحجب.", "الأب عاصب، فقد يأخذ فرضه مع أصحاب الفرائض وما بقي يرثه بالتعصيب، لقوله ﷺ: «ألحقوا الفرائض بأهلها، فما أبقت الفرائض فلأولى رجل ذكر»."], "k": "«لا تدرون أيهم أقرب لكم نفعاً»… هل أرضى بقسمة الله في الرزق، أم في قلبي اعتراض خفيّ؟"}, {"lbl": "الآية ١٢", "q": "۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ ﴿١٢﴾", "w": [["أزواجكم", "الأزواج هنا الزوجات."], ["ولد", "المراد ابن الصلب ذكراً كان أو أنثى، وولد الولد مثله."], ["الربع", "واحد من أربعة."], ["كلالة", "أن يهلك هالك ولا يترك ولداً ولا والداً."], ["وله أخ أو أخت", "أي من الأم."], ["غير مضارّ", "غير مضارّ بالوصية والدين أحداً من الورثة."], ["حليم", "لا يعاجل بالعقوبة على المعصية."]], "m": "كانت الآية قبلها في الوراثة بالنسب، وجاءت هذه في الوراثة بالمصاهرة، والوارثون بها الزوج والزوجات. فمن ماتت ولم تترك ولداً ولا ولد ولد فلزوجها النصف، وإن تركت ولداً أو ولد ولد فلزوجها الربع، بعد سداد دينها وإخراج وصيتها. وأما الزوجة فلها الربع إن لم يترك الزوج ولداً ولا ولد ولد، فإن ترك فلها الثمن، وإن كن زوجتين أو أكثر اشتركن في الربع أو الثمن بالتساوي. ثم ذكر الكلالة، وهو من ليس له والد ولا ولد، فيرثه إخوته لأمه كما في هذه الآية: فإن كان له أخ أو أخت من الأم فلكلٍّ السدس، وإن كانوا أكثر فهم شركاء في الثلث، بعد وصية أو دين غير مضارّ، بأن يوصي بأكثر من الثلث أو يقرّ بدين ليس عليه حسداً للورثة أو بغضاً لهم، فإن تبيّن ذلك لم تنفذ الوصية ولم يُسدّد الدين. وصيّةً من الله، جديرة بالاحترام والامتثال، والله عليم بنياتكم، حليم لا يعاجل بالعقوبة، فلا يغرّنكم حلمه.", "h": ["بيان ميراث الزوج من زوجته، والزوجة والزوجات من زوجهن.", "بيان ميراث الكلالة، وهو من لا يترك والداً ولا ولداً فيرثه إخوته، يحيطون به إحاطة الإكليل بالرأس، فلذا سُمّيت الكلالة.", "إهمال الوصية أو الدين إن عُلم أن الغرض منهما الإضرار بالورثة فقط.", "عظم شأن المواريث، فيجب معرفة ذلك وتنفيذه كما وصّى الله تعالى."], "k": "«غير مضارّ»… هل في نيتي أو وصيتي ما يضرّ أحداً من أهلي ولو بغير قصد؟"}, {"lbl": "الآيتان ١٣ – ١٤", "q": "تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٣﴾ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ ﴿١٤﴾", "w": [["تلك حدود الله", "إشارة إلى ما تقدّم من أحكام النكاح وكفالة اليتامى وتحريم أكل مال اليتيم وقسمة التركات، وحدود الله: ما حدّه لنا وبيّنه من طاعته، وحرّم علينا الخروج عنه والتعدّي له."], ["الفوز العظيم", "النجاة من النار ودخول الجنة."], ["العذاب المهين", "ما كان فيه إهانة للمعذَّب بالتقريع والتوبيخ ونحو ذلك."]], "m": "لما بيّن الله ما شاء من أحكام الشرع وحدود الدين، أشار إلى ذلك بقوله: تلك حدود الله قد بيّنتها لكم وأمرتكم بالتزامها، فمن يطع الله ورسوله فيها وفي غيرها من الشرائع والأحكام فجزاؤه أن يدخله جنات تجري من تحتها الأنهار، أنهار العسل واللبن والخمر والماء، خالداً فيها أبداً، وذلك هو الفوز العظيم؛ إذ نجّاه من النار وأدخله الجنة. ومن يعصِ الله ورسوله بتعدّي تلك الحدود وغيرها، ومات على ذلك، فجزاؤه أن يدخله ناراً يخلد فيها، وله عذاب مهين.", "h": ["بيان حرمة تعدّي حدود الله تعالى.", "بيان ثواب طاعة الله ورسوله، وهو الخلود في الجنة."], "k": "«تلك حدود الله»… هل أقف عند حدود الله في بيتي ومالي وحقوق أهلي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 66;
insert into public.tdb_cards(topic, i, body) select 66, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧ – ١٠", "q": "لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا ﴿٧﴾ وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ﴿٨﴾ وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا ﴿٩﴾ إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا ﴿١٠﴾", "w": [["نصيب", "الحظ المقدّر في كتاب الله."], ["الوالدان", "الأب والأم."], ["الأقربون", "جمع قريب، وهو هنا الوارث بنسب أو مصاهرة أو ولاء."], ["نصيباً مفروضاً", "قدراً واجباً لازماً."], ["أولو القربى", "أصحاب القرابات الذين لا يرثون لبعدهم عن عمودي النسب."], ["فارزقوهم منه", "أعطوهم شيئاً يرزقونه."], ["قولاً معروفاً", "لا إهانة فيه ولا عتاب ولا تأفيف."], ["وليخش", "الخشية: الخوف في موضع الأمن."], ["قولاً سديداً", "عدلاً صائباً."], ["ظلماً", "بغير حق يخوّل لهم أكل مال اليتيم."], ["وسيصلون سعيراً", "سيدخلون ناراً مستعرة يُشوَون فيها."]], "m": "كان أهل الجاهلية لا يورّثون النساء ولا الأطفال، بحجة أنهم لا يركبون فرساً ولا يحملون كلّاً ولا ينكؤون عدواً، وحدث أن امرأة يقال لها أم كُجّة مات زوجها وترك لها بنتين، فمنعهما أخو الهالك من الإرث، فشكت إلى رسول الله ﷺ، فنزلت: «للرجال نصيب مما ترك الوالدان والأقربون، وللنساء نصيب مما ترك الوالدان والأقربون»، قلّ المال أو كثر، نصيباً مفروضاً لا بد من إعطائه للوارث ذكراً أو أنثى، صغيراً أو كبيراً. ثم ذكر فضيلة غفل عنها المؤمنون: إذا حضر قسمة التركة قريب غير وارث أو يتيم أو مسكين، فمن المعروف أن يُعطَوا منها شيئاً، فإن تعذّر لأن الورثة يتامى صُرفوا بكلمة طيبة. ثم أرشد من يحضر مريضاً على فراش الموت ألا يدعه يحيف في الوصية، بأن يوصي لوارث أو بأكثر من الثلث، فليخشَ على أولاد غيره ما يخشاه على أولاده الضعاف من بعده، وليتّق الله وليقل قولاً سديداً. ثم توعّد من يأكل أموال اليتامى ظلماً بأنهم إنما يأكلون في بطونهم ناراً، باعتبار ما يؤول إليه أمرهم، وسيصلون سعيراً.", "h": ["تقرير مبدأ التوارث في الإسلام.", "استحباب إعطاء من حضر قسمة التركة من قريب أو يتيم أو مسكين، وإن تعذّر إعطاؤهم صُرفوا بالكلمة الطيبة، وفي الحديث: «الكلمة الطيبة صدقة».", "وجوب النصح والإرشاد للمحتضر حتى لا يجور في وصيته عند موته.", "على من يخاف على أطفاله بعد موته أن يحسن إلى أطفال غيره، فإن الله تعالى يكفيه فيهم.", "حرمة أكل مال اليتامى ظلماً، والوعيد الشديد فيه."], "k": "«فليتقوا الله وليقولوا قولاً سديداً»… كيف أحب أن يُعامَل أولادي من بعدي؟ وهل أعامل أبناء غيري كذلك؟"}, {"lbl": "الآية ١١", "q": "يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿١١﴾", "w": [["يوصيكم", "يعهد إليكم."], ["في أولادكم", "في شأن أولادكم، والولد يطلق على الذكر والأنثى."], ["حظ", "الحصة أو النصيب."], ["نساء", "بنات كبيرات أو صغيرات."], ["ثلثا ما ترك", "الثلث واحد من ثلاثة، والثلثان اثنان من ثلاثة."], ["السدس", "واحد من ستة."], ["إن كان له ولد", "ذكراً كان أو أنثى، أو ولد ولد كذلك."], ["فإن كان له إخوة", "اثنان فأكثر."], ["من بعد وصية", "بعد الدَّين ثم الوصية، ويُقسم الباقي على الورثة."], ["لا تدرون", "لا تعلمون."], ["فريضة", "فرض الله ذلك عليكم فريضة."], ["عليماً حكيماً", "عليماً بخلقه وما يصلح لهم، حكيماً في تدبيره لشؤونهم."]], "m": "نزلت هذه الآية والتي بعدها لتفصيل ما أجملته آية «للرجال نصيب». فبيّن الله توارث الأبناء مع الآباء: إذا مات الرجل وترك أولاداً ذكوراً وإناثاً قُسمت التركة للذكر مثل حظ الأنثيين، فلو ترك ولداً وبنتاً وثلاثة دنانير أخذ الولد دينارين والبنت ديناراً. وإن ترك بنتين فأكثر ولا ذكر معهن فلهن الثلثان والباقي للعصبة، وإن ترك بنتاً واحدة فلها النصف والباقي للعصبة. وإن ترك أبويه مع أولاده فلكل واحد من الأبوين السدس، وإن لم يكن له ولد ولا ولد ولد فلأمه الثلث، فإن كان له إخوة اثنان فأكثر حجبوها من الثلث إلى السدس. وكل ذلك بعد قضاء دين الميت وإخراج وصيته إن كانت الثلث فأقل. ثم قال: آباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعاً، فنفّذوا القسمة كما علّمكم الله بلا محاباة، فإنها فريضة من عليم حكيم، فليرضَ العبد بها.", "h": ["أن الله تعالى تولّى قسمة التركات بنفسه، فلا يحل لأحد أن يغيّر منها شيئاً.", "الاثنان يُعتبران جمعاً.", "ولد الولد حكمه حكم الولد نفسه في الحجب.", "الأب عاصب، فقد يأخذ فرضه مع أصحاب الفرائض وما بقي يرثه بالتعصيب، لقوله ﷺ: «ألحقوا الفرائض بأهلها، فما أبقت الفرائض فلأولى رجل ذكر»."], "k": "«لا تدرون أيهم أقرب لكم نفعاً»… هل أرضى بقسمة الله في الرزق، أم في قلبي اعتراض خفيّ؟"}, {"lbl": "الآية ١٢", "q": "۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ ﴿١٢﴾", "w": [["أزواجكم", "الأزواج هنا الزوجات."], ["ولد", "المراد ابن الصلب ذكراً كان أو أنثى، وولد الولد مثله."], ["الربع", "واحد من أربعة."], ["كلالة", "أن يهلك هالك ولا يترك ولداً ولا والداً."], ["وله أخ أو أخت", "أي من الأم."], ["غير مضارّ", "غير مضارّ بالوصية والدين أحداً من الورثة."], ["حليم", "لا يعاجل بالعقوبة على المعصية."]], "m": "كانت الآية قبلها في الوراثة بالنسب، وجاءت هذه في الوراثة بالمصاهرة، والوارثون بها الزوج والزوجات. فمن ماتت ولم تترك ولداً ولا ولد ولد فلزوجها النصف، وإن تركت ولداً أو ولد ولد فلزوجها الربع، بعد سداد دينها وإخراج وصيتها. وأما الزوجة فلها الربع إن لم يترك الزوج ولداً ولا ولد ولد، فإن ترك فلها الثمن، وإن كن زوجتين أو أكثر اشتركن في الربع أو الثمن بالتساوي. ثم ذكر الكلالة، وهو من ليس له والد ولا ولد، فيرثه إخوته لأمه كما في هذه الآية: فإن كان له أخ أو أخت من الأم فلكلٍّ السدس، وإن كانوا أكثر فهم شركاء في الثلث، بعد وصية أو دين غير مضارّ، بأن يوصي بأكثر من الثلث أو يقرّ بدين ليس عليه حسداً للورثة أو بغضاً لهم، فإن تبيّن ذلك لم تنفذ الوصية ولم يُسدّد الدين. وصيّةً من الله، جديرة بالاحترام والامتثال، والله عليم بنياتكم، حليم لا يعاجل بالعقوبة، فلا يغرّنكم حلمه.", "h": ["بيان ميراث الزوج من زوجته، والزوجة والزوجات من زوجهن.", "بيان ميراث الكلالة، وهو من لا يترك والداً ولا ولداً فيرثه إخوته، يحيطون به إحاطة الإكليل بالرأس، فلذا سُمّيت الكلالة.", "إهمال الوصية أو الدين إن عُلم أن الغرض منهما الإضرار بالورثة فقط.", "عظم شأن المواريث، فيجب معرفة ذلك وتنفيذه كما وصّى الله تعالى."], "k": "«غير مضارّ»… هل في نيتي أو وصيتي ما يضرّ أحداً من أهلي ولو بغير قصد؟"}, {"lbl": "الآيتان ١٣ – ١٤", "q": "تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٣﴾ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ ﴿١٤﴾", "w": [["تلك حدود الله", "إشارة إلى ما تقدّم من أحكام النكاح وكفالة اليتامى وتحريم أكل مال اليتيم وقسمة التركات، وحدود الله: ما حدّه لنا وبيّنه من طاعته، وحرّم علينا الخروج عنه والتعدّي له."], ["الفوز العظيم", "النجاة من النار ودخول الجنة."], ["العذاب المهين", "ما كان فيه إهانة للمعذَّب بالتقريع والتوبيخ ونحو ذلك."]], "m": "لما بيّن الله ما شاء من أحكام الشرع وحدود الدين، أشار إلى ذلك بقوله: تلك حدود الله قد بيّنتها لكم وأمرتكم بالتزامها، فمن يطع الله ورسوله فيها وفي غيرها من الشرائع والأحكام فجزاؤه أن يدخله جنات تجري من تحتها الأنهار، أنهار العسل واللبن والخمر والماء، خالداً فيها أبداً، وذلك هو الفوز العظيم؛ إذ نجّاه من النار وأدخله الجنة. ومن يعصِ الله ورسوله بتعدّي تلك الحدود وغيرها، ومات على ذلك، فجزاؤه أن يدخله ناراً يخلد فيها، وله عذاب مهين.", "h": ["بيان حرمة تعدّي حدود الله تعالى.", "بيان ثواب طاعة الله ورسوله، وهو الخلود في الجنة."], "k": "«تلك حدود الله»… هل أقف عند حدود الله في بيتي ومالي وحقوق أهلي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (67, 4, 15, 23, 'سورة النساء ١٥ – ٢٣', 'التوبة المقبولة، ومعاشرة النساء بالمعروف، والمحرّمات من النساء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 67) = $j$[{"lbl": "الآيات ١٥ – ١٨", "q": "وَٱلَّـٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا ﴿١٥﴾ وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا ﴿١٦﴾ إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١٧﴾ وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَـٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا ﴿١٨﴾", "w": [["واللاتي", "جمع «التي»."], ["الفاحشة", "المراد بها هنا الزنى."], ["من نسائكم", "المحصنات."], ["يأتيانها", "الضمير عائد إلى الفاحشة."], ["فأعرضوا عنهما", "اتركوا أذيتهما بعد أن ظهرت توبتهما."], ["التوبة", "أصلها الرجوع، وحقيقتها الندم على فعل القبيح مع تركه، والعزم على عدم العودة إليه."], ["السوء", "كل ما أساء إلى النفس، والمراد به هنا السيئات."], ["بجهالة", "بغير علم، لا مع العمد والإصرار وعدم المبالاة."], ["أعتدنا", "أعددنا وهيّأنا."], ["أليماً", "موجعاً شديد الإيجاع."]], "m": "لما ذكر الله حدوده وجزاء متعدّيها، ذكر معصية من معاصيه وهي فاحشة الزنى، ووضع لها حداً أوّلاً: الحبس في البيوت للمحصنات حتى الموت أو يجعل الله لهن سبيلاً، بعد أن يشهد عليهن أربعة من المسلمين، وأما غير المحصنين فيؤذَون بالتقريع والعتاب حتى يتوبوا ويصلحوا فيُكفّ عنهم. ولم يمضِ إلا قليل حتى جعل الله لهن سبيلاً، فقال ﷺ: «خذوا عني، خذوا عني، قد جعل الله لهن سبيلاً»، فنُسخ الحدّ الأول، ونزل في جلد البكر آية النور، ومضت السنة في رجم المحصن. ثم أخبر أن التوبة التي تفضّل الله بقبولها هي للذين يعملون السوء بجهالة، لا بعناد ومكابرة، ثم يتوبون من قريب لا يسوّفون، فأولئك يتوب الله عليهم، وكان عليماً بضعف عباده حكيماً. وليست التوبة للذين يعملون السيئات ويؤخّرون التوبة حتى إذا حضر أحدهم الموت قال: إني تبت الآن، ولا للذين يموتون وهم كفار، كفرعون لما أدركه الغرق قال آمنت، فقيل له: «آلآن وقد عصيت قبل». أولئك أعتدنا لهم عذاباً أليماً، إلا أن المؤمن الموحّد يخرج من النار بإيمانه، والكافر يخلد فيها.", "h": ["عظم قبح فاحشة الزنى.", "بيان حدّ الزنى قبل نسخه بآية سورة النور، وحكم الرسول ﷺ في رجم المحصن.", "التوبة التي تفضّل الله بها هي ما كان صاحبها أتى ما أتى من الذنوب بجهالة لا بعلم وإصرار، ثم تاب من قريب زمن.", "الذين يسوّفون التوبة ويؤخّرونها يُخشى عليهم ألا يتوبوا حتى يدركهم الموت، وتُقبل توبة أحدهم إذا لم يعاين أمارات الموت، لقوله ﷺ: «إن الله يقبل توبة العبد ما لم يغرغر».", "لا تُقبل توبة من حشرجت نفسه وظهرت عليه علامات الموت، وكذا الكافر من باب أولى، كما لم تُقبل توبة فرعون."], "k": "«ثم يتوبون من قريب»… ما الذنب الذي أؤجّل التوبة منه؟ ولماذا لا أتوب منه الآن؟"}, {"lbl": "الآيات ١٩ – ٢١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا ﴿١٩﴾ وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿٢٠﴾ وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا ﴿٢١﴾", "w": [["ولا تعضلوهن", "العضل: المنع بشدة."], ["ببعض ما آتيتموهن", "من المهور."], ["بفاحشة مبينة", "خصلة شديدة القبح كالزنى، ظاهرة واضحة ليست مجرد تهمة."], ["بالمعروف", "ما عرفه الشرع واجباً أو مندوباً أو مباحاً."], ["قنطاراً", "من الذهب أو الفضة مهراً وصداقاً."], ["بهتاناً وإثماً", "كذباً وافتراءً، وحراماً لا شك في حرمته لأنه ظلم."], ["أفضى بعضكم إلى بعض", "خلص كل من الزوجين إلى الآخر."], ["ميثاقاً غليظاً", "عقد النكاح، وقول الزوج: إمساك بمعروف أو تسريح بإحسان."]], "m": "أبطلت الآية ظلماً كان شائعاً قبل الإسلام: كان الرجل إذا مات عن زوجته ورثها أكبر أولاده من غيرها، فإن شاء زوّجها وأخذ مهرها، وإن شاء أمسكها حتى تعطيه ما يطلب، فأنزل الله: «لا يحل لكم أن ترثوا النساء كرهاً»، فأصبحت المرأة إذا مات زوجها اعتدّت في بيته، فإذا انقضت عدتها ذهبت حيث شاءت بمالها وما ورثته. ثم حرّم على الزوج إذا كره زوجته أن يضايقها لتفتدي منه بمهرها، إلا أن تأتي بفاحشة مبينة أو تنشز نشوزاً بيّناً. ثم أمر بمعاشرتهن بالمعروف، وهو العدل والإحسان، وإن كره أحدكم زوجته وهي لم تأتِ بفاحشة فليصبر ولا يطلّق، فعسى أن يجعل الله في بقائها خيراً كثيراً، فقد يُرزق منها ولداً صالحاً، وقد يذهب الكره ويحلّ محله الحب والمودة. ثم حرّم أخذ شيء من مهر المرأة إذا أراد الزوج طلاقها ليتزوج غيرها، ولو كان قد أمهرها قنطاراً، فكيف تأخذونه بهتاناً وإثماً مبيناً، وقد أفضى بعضكم إلى بعض، وأخذن منكم ميثاقاً غليظاً؟", "h": ["إبطال قانون الجاهلية القائم على أن ابن الزوج يرث امرأة أبيه.", "حرمة العضل من أجل الافتداء بالمهر وغيره.", "الترغيب في الصبر.", "جواز أخذ الفدية من الزوجة بالمهر أو أكثر أو أقل إن هي أتت بفاحشة ظاهرة لا شك فيها كالزنى أو النشوز.", "جواز غلاء المهر، فقد يبلغ القنطار، غير أن التيسير فيه أكثر بركة.", "وجوب مراعاة العهود والوفاء بها."], "k": "«فعسى أن تكرهوا شيئاً ويجعل الله فيه خيراً كثيراً»… ما الذي أكرهه اليوم وقد يكون فيه خير لي؟"}, {"lbl": "الآيتان ٢٢ – ٢٣", "q": "وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا ﴿٢٢﴾ حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّـٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّـٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَـٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿٢٣﴾", "w": [["ولا تنكحوا ما نكح آباؤكم", "لا تتزوجوا امرأة الأب أو الجد."], ["إلا ما قد سلف", "إلا ما قد مضى قبل هذا التحريم."], ["إنه كان فاحشة", "زواج نساء الآباء فاحشة شديدة القبح."], ["ومقتاً", "ممقوتاً مبغوضاً للشارع ولكل ذي فطرة سليمة."], ["وساء سبيلاً", "قبُح نكاح أزواج الآباء طريقاً يُسلك."], ["أمهاتكم", "جمع أم، ومثلها الجدة وإن علت."], ["وربائبكم", "جمع ربيبة، وهي بنت الزوجة."], ["وحلائل أبنائكم", "جمع حليلة، وهي امرأة الابن من الصلب."]], "m": "ما زال السياق في بيان الأحكام المتعلقة بالإرث والنكاح وعشرة النساء، وفي هاتين الآيتين ذكر الله محرمات النكاح من النسب والرضاع والمصاهرة. فبدأ بتحريم امرأة الأب وإن علا، ولو لم يدخل بها الأب، إلا ما قد سلف في الجاهلية فإنه معفوّ عنه بعد التخلّي عنه. ثم ذكر محرمات النسب السبع: الأمهات، والبنات، والأخوات، والعمات، والخالات، وبنات الأخ، وبنات الأخت. ثم المحرمات بالرضاع: فمن رضع من امرأة خمس رضعات وهو في سن الحولين حرمت عليه، وحرمت عليه أمهاتها وبناتها وأخواتها، وكذا قرابات زوجها، فيحرم من الرضاعة ما يحرم من النسب. ثم المحرمات بالمصاهرة: أم الزوجة بمجرد العقد على بنتها، والربيبة إذا دخل بأمها، فإن لم يدخل بها فلا جناح، وزوجة الابن من الصلب، دخل بها أو لم يدخل، لا ابن التبنّي، والابن من الرضاع كابن الصلب. ومنها الجمع بين الأختين، فلا يتزوج أخت زوجته حتى تموت أو يفارقها وتنتهي عدتها، إلا ما قد سلف في الجاهلية.", "h": ["تحريم مناكح الجاهلية إلا ما وافق الإسلام منها، وخاصة أزواج الآباء، فزوجة الأب محرمة على الابن ولو لم يدخل بها الأب.", "بيان المحرمات من النسب، وهن سبع: الأمهات، والبنات، والأخوات، والعمات، والخالات، وبنات الأخ، وبنات الأخت.", "بيان المحرمات من الرضاع، وهن نظير المحرمات من النسب.", "بيان المحرمات من المصاهرة: زوجة الأب، وأم الزوجة، وبنتها إذا دخل بأمها، وامرأة الولد من الصلب أو من الرضاع، وأخت الزوجة ما دامت أختها في عصمته، والمتزوجات حتى يُطلّقن أو يموت أزواجهن وتنقضي عددهن."], "k": "حدود الله في الأسرة تحفظ الأنساب والأرحام… هل أعرف أحكام بيتي كما أعرف أمور دنياي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 67;
insert into public.tdb_cards(topic, i, body) select 67, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥ – ١٨", "q": "وَٱلَّـٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا ﴿١٥﴾ وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا ﴿١٦﴾ إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١٧﴾ وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَـٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا ﴿١٨﴾", "w": [["واللاتي", "جمع «التي»."], ["الفاحشة", "المراد بها هنا الزنى."], ["من نسائكم", "المحصنات."], ["يأتيانها", "الضمير عائد إلى الفاحشة."], ["فأعرضوا عنهما", "اتركوا أذيتهما بعد أن ظهرت توبتهما."], ["التوبة", "أصلها الرجوع، وحقيقتها الندم على فعل القبيح مع تركه، والعزم على عدم العودة إليه."], ["السوء", "كل ما أساء إلى النفس، والمراد به هنا السيئات."], ["بجهالة", "بغير علم، لا مع العمد والإصرار وعدم المبالاة."], ["أعتدنا", "أعددنا وهيّأنا."], ["أليماً", "موجعاً شديد الإيجاع."]], "m": "لما ذكر الله حدوده وجزاء متعدّيها، ذكر معصية من معاصيه وهي فاحشة الزنى، ووضع لها حداً أوّلاً: الحبس في البيوت للمحصنات حتى الموت أو يجعل الله لهن سبيلاً، بعد أن يشهد عليهن أربعة من المسلمين، وأما غير المحصنين فيؤذَون بالتقريع والعتاب حتى يتوبوا ويصلحوا فيُكفّ عنهم. ولم يمضِ إلا قليل حتى جعل الله لهن سبيلاً، فقال ﷺ: «خذوا عني، خذوا عني، قد جعل الله لهن سبيلاً»، فنُسخ الحدّ الأول، ونزل في جلد البكر آية النور، ومضت السنة في رجم المحصن. ثم أخبر أن التوبة التي تفضّل الله بقبولها هي للذين يعملون السوء بجهالة، لا بعناد ومكابرة، ثم يتوبون من قريب لا يسوّفون، فأولئك يتوب الله عليهم، وكان عليماً بضعف عباده حكيماً. وليست التوبة للذين يعملون السيئات ويؤخّرون التوبة حتى إذا حضر أحدهم الموت قال: إني تبت الآن، ولا للذين يموتون وهم كفار، كفرعون لما أدركه الغرق قال آمنت، فقيل له: «آلآن وقد عصيت قبل». أولئك أعتدنا لهم عذاباً أليماً، إلا أن المؤمن الموحّد يخرج من النار بإيمانه، والكافر يخلد فيها.", "h": ["عظم قبح فاحشة الزنى.", "بيان حدّ الزنى قبل نسخه بآية سورة النور، وحكم الرسول ﷺ في رجم المحصن.", "التوبة التي تفضّل الله بها هي ما كان صاحبها أتى ما أتى من الذنوب بجهالة لا بعلم وإصرار، ثم تاب من قريب زمن.", "الذين يسوّفون التوبة ويؤخّرونها يُخشى عليهم ألا يتوبوا حتى يدركهم الموت، وتُقبل توبة أحدهم إذا لم يعاين أمارات الموت، لقوله ﷺ: «إن الله يقبل توبة العبد ما لم يغرغر».", "لا تُقبل توبة من حشرجت نفسه وظهرت عليه علامات الموت، وكذا الكافر من باب أولى، كما لم تُقبل توبة فرعون."], "k": "«ثم يتوبون من قريب»… ما الذنب الذي أؤجّل التوبة منه؟ ولماذا لا أتوب منه الآن؟"}, {"lbl": "الآيات ١٩ – ٢١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا ﴿١٩﴾ وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ﴿٢٠﴾ وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا ﴿٢١﴾", "w": [["ولا تعضلوهن", "العضل: المنع بشدة."], ["ببعض ما آتيتموهن", "من المهور."], ["بفاحشة مبينة", "خصلة شديدة القبح كالزنى، ظاهرة واضحة ليست مجرد تهمة."], ["بالمعروف", "ما عرفه الشرع واجباً أو مندوباً أو مباحاً."], ["قنطاراً", "من الذهب أو الفضة مهراً وصداقاً."], ["بهتاناً وإثماً", "كذباً وافتراءً، وحراماً لا شك في حرمته لأنه ظلم."], ["أفضى بعضكم إلى بعض", "خلص كل من الزوجين إلى الآخر."], ["ميثاقاً غليظاً", "عقد النكاح، وقول الزوج: إمساك بمعروف أو تسريح بإحسان."]], "m": "أبطلت الآية ظلماً كان شائعاً قبل الإسلام: كان الرجل إذا مات عن زوجته ورثها أكبر أولاده من غيرها، فإن شاء زوّجها وأخذ مهرها، وإن شاء أمسكها حتى تعطيه ما يطلب، فأنزل الله: «لا يحل لكم أن ترثوا النساء كرهاً»، فأصبحت المرأة إذا مات زوجها اعتدّت في بيته، فإذا انقضت عدتها ذهبت حيث شاءت بمالها وما ورثته. ثم حرّم على الزوج إذا كره زوجته أن يضايقها لتفتدي منه بمهرها، إلا أن تأتي بفاحشة مبينة أو تنشز نشوزاً بيّناً. ثم أمر بمعاشرتهن بالمعروف، وهو العدل والإحسان، وإن كره أحدكم زوجته وهي لم تأتِ بفاحشة فليصبر ولا يطلّق، فعسى أن يجعل الله في بقائها خيراً كثيراً، فقد يُرزق منها ولداً صالحاً، وقد يذهب الكره ويحلّ محله الحب والمودة. ثم حرّم أخذ شيء من مهر المرأة إذا أراد الزوج طلاقها ليتزوج غيرها، ولو كان قد أمهرها قنطاراً، فكيف تأخذونه بهتاناً وإثماً مبيناً، وقد أفضى بعضكم إلى بعض، وأخذن منكم ميثاقاً غليظاً؟", "h": ["إبطال قانون الجاهلية القائم على أن ابن الزوج يرث امرأة أبيه.", "حرمة العضل من أجل الافتداء بالمهر وغيره.", "الترغيب في الصبر.", "جواز أخذ الفدية من الزوجة بالمهر أو أكثر أو أقل إن هي أتت بفاحشة ظاهرة لا شك فيها كالزنى أو النشوز.", "جواز غلاء المهر، فقد يبلغ القنطار، غير أن التيسير فيه أكثر بركة.", "وجوب مراعاة العهود والوفاء بها."], "k": "«فعسى أن تكرهوا شيئاً ويجعل الله فيه خيراً كثيراً»… ما الذي أكرهه اليوم وقد يكون فيه خير لي؟"}, {"lbl": "الآيتان ٢٢ – ٢٣", "q": "وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا ﴿٢٢﴾ حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّـٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّـٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَـٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿٢٣﴾", "w": [["ولا تنكحوا ما نكح آباؤكم", "لا تتزوجوا امرأة الأب أو الجد."], ["إلا ما قد سلف", "إلا ما قد مضى قبل هذا التحريم."], ["إنه كان فاحشة", "زواج نساء الآباء فاحشة شديدة القبح."], ["ومقتاً", "ممقوتاً مبغوضاً للشارع ولكل ذي فطرة سليمة."], ["وساء سبيلاً", "قبُح نكاح أزواج الآباء طريقاً يُسلك."], ["أمهاتكم", "جمع أم، ومثلها الجدة وإن علت."], ["وربائبكم", "جمع ربيبة، وهي بنت الزوجة."], ["وحلائل أبنائكم", "جمع حليلة، وهي امرأة الابن من الصلب."]], "m": "ما زال السياق في بيان الأحكام المتعلقة بالإرث والنكاح وعشرة النساء، وفي هاتين الآيتين ذكر الله محرمات النكاح من النسب والرضاع والمصاهرة. فبدأ بتحريم امرأة الأب وإن علا، ولو لم يدخل بها الأب، إلا ما قد سلف في الجاهلية فإنه معفوّ عنه بعد التخلّي عنه. ثم ذكر محرمات النسب السبع: الأمهات، والبنات، والأخوات، والعمات، والخالات، وبنات الأخ، وبنات الأخت. ثم المحرمات بالرضاع: فمن رضع من امرأة خمس رضعات وهو في سن الحولين حرمت عليه، وحرمت عليه أمهاتها وبناتها وأخواتها، وكذا قرابات زوجها، فيحرم من الرضاعة ما يحرم من النسب. ثم المحرمات بالمصاهرة: أم الزوجة بمجرد العقد على بنتها، والربيبة إذا دخل بأمها، فإن لم يدخل بها فلا جناح، وزوجة الابن من الصلب، دخل بها أو لم يدخل، لا ابن التبنّي، والابن من الرضاع كابن الصلب. ومنها الجمع بين الأختين، فلا يتزوج أخت زوجته حتى تموت أو يفارقها وتنتهي عدتها، إلا ما قد سلف في الجاهلية.", "h": ["تحريم مناكح الجاهلية إلا ما وافق الإسلام منها، وخاصة أزواج الآباء، فزوجة الأب محرمة على الابن ولو لم يدخل بها الأب.", "بيان المحرمات من النسب، وهن سبع: الأمهات، والبنات، والأخوات، والعمات، والخالات، وبنات الأخ، وبنات الأخت.", "بيان المحرمات من الرضاع، وهن نظير المحرمات من النسب.", "بيان المحرمات من المصاهرة: زوجة الأب، وأم الزوجة، وبنتها إذا دخل بأمها، وامرأة الولد من الصلب أو من الرضاع، وأخت الزوجة ما دامت أختها في عصمته، والمتزوجات حتى يُطلّقن أو يموت أزواجهن وتنقضي عددهن."], "k": "حدود الله في الأسرة تحفظ الأنساب والأرحام… هل أعرف أحكام بيتي كما أعرف أمور دنياي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;